// Dibuat: 2026-10-04 17:12 WIB | 142 artikel | JANGAN edit manual — regenerasi via tools/kb-sync.mjs.
export const KB_ARTICLES = [{"i":"seo-satu-h1-dan-judul-unik","c":"seo","cn":"SEO On-Page","t":"Cara Jaga Satu H1 dan Judul Halaman yang Unik","d":"Tata cara memberi tiap halaman Clincoo satu h1 dan title yang menyebut topik halaman, bukan nama merek yang diulang di semua URL.","x":"Mesin telusur memakai title dan h1 untuk membedakan URL. Di editor.clincoo.buzz tulis title yang menyebut tugas halaman, lalu satu h1 dengan kata yang sama. Jangan duplikat title template Halaman tentang, harga, dan blog tidak boleh memakai title yang sama. Tambahkan nama bagian di depan merek Clincoo. Satu h1, heading lain di bawahnya H1 hanya sekali di konten utama. Subbagian memakai h2. Cek pratinjau app.clincoo.buzz dengan outline dokumen. Samakan janji title dan paragraf pertama Kalau title menjanjikan cara deploy, paragraf pertama harus itu. Simpan contoh title di blog.clincoo.buzz ."},{"i":"seo-meta-description-yang-spesifik","c":"seo","cn":"SEO On-Page","t":"Cara Tulis Meta Description yang Spesifik","d":"Tata cara menulis meta description Clincoo yang menyebut hasil halaman, bukan slogan umum, supaya cuplikan telusur tidak diisi teks acak.","x":"Meta description bukan peringkat langsung, tetapi menjadi cuplikan. Di editor.clincoo.buzz tulis satu atau dua kalimat yang menyebut apa yang pengguna dapat. Sebut objek dan tindakan Contoh buruk: solusi terbaik untuk bisnis. Contoh baik: cara mengekspor situs Clincoo dan memeriksa tautan yang putus sebelum domain kustom. Jangan salin deskripsi antarhalaman Deskripsi kembar membuat cuplikan sama. Bedakan tiap URL. Pratinjau cuplikan di app.clincoo.buzz dengan melihat tag head. Panjang cukup untuk satu ide Cukup sekitar 120–160 karakter. Simpan rumus ini di blog.clincoo.buzz ."},{"i":"seo-heading-jangan-lompat-level","c":"seo","cn":"SEO On-Page","t":"Cara Susun Heading Tanpa Melompati Level","d":"Tata cara menyusun h1 lalu h2 lalu h3 di halaman Clincoo supaya outline dokumen masuk akal bagi pembaca layar dan mesin telusur.","x":"Heading adalah kerangka, bukan ukuran font. Di editor.clincoo.buzz jangan lompat dari h1 ke h4 hanya karena ingin teks lebih kecil. Turunkan satu level saat masuk subbagian Setelah h2, detail memakai h3. Kembali ke h2 saat topik baru di level yang sama. Jangan pakai heading untuk label tombol Teks tombol tetap span atau teks tombol. Heading hanya untuk bagian. Uji outline di pratinjau app.clincoo.buzz . Samakan bahasa heading dengan isi Heading yang janji langkah harus diikuti langkah. Catat pola di blog.clincoo.buzz ."},{"i":"seo-tautan-internal-anchor-jelas","c":"seo","cn":"SEO On-Page","t":"Cara Tulis Anchor Tautan Internal yang Jelas","d":"Tata cara menulis teks tautan internal Clincoo yang menyebut halaman tujuan, bukan kata klik di sini yang diulang di setiap paragraf.","x":"Anchor adalah petunjuk tujuan. Di editor.clincoo.buzz ganti klik di sini dengan nama halaman, misalnya panduan deploy domain kustom. Satu tautan, satu tujuan Jangan menumpuk dua URL pada kalimat yang sama jika pembaca hanya butuh satu langkah berikutnya. Hindari anchor yang sama untuk URL beda Selengkapnya yang mengarah ke halaman berbeda membingungkan. Sebut topik. Cek di app.clincoo.buzz bahwa href relatif masih benar setelah pindah folder. Tautan keluar tetap rel noopener Tautan ke blog.clincoo.buzz memakai target blank dan rel noopener. Tautan internal cukup href biasa."},{"i":"seo-lebar-tinggi-gambar-cegah-cls","c":"seo","cn":"SEO On-Page","t":"Cara Isi Width dan Height Gambar supaya Layout Tidak Melompat","d":"Tata cara menaruh width dan height pada img di halaman Clincoo supaya ruang gambar sudah dipesan sebelum berkas selesai diunduh.","x":"Gambar tanpa ukuran membuat teks di bawahnya meloncat saat berkas selesai. Di editor.clincoo.buzz isi width dan height sesuai rasio asli, bukan angka sembarang. Pakai ukuran intrinsik Jika foto 1200×800, tulis width=\"1200\" height=\"800\". CSS boleh mengecilkan dengan max-width: 100% dan height: auto. Jangan hapus atributnya hanya karena layout sudah memakai persen. Jangan tipu rasio Width 100 dan height 100 pada foto lebar memaksa kotak yang salah lalu terkoreksi. Rasio atribut harus sama dengan berkas. Gambar hias tetap butuh alt kosong, bukan ukuran yang dihilangkan. Cek di preview Di app.clincoo.buzz muat ulang dengan jaringan lambat. Teks di bawah gambar tidak boleh bergeser. Catat pola ini di blog.clincoo.buzz ."},{"i":"seo-loading-lazy-gambar-bawah-lipatan","c":"seo","cn":"SEO On-Page","t":"Cara Pasang loading lazy pada Gambar di Bawah Lipatan","d":"Tata cara menunda unduhan gambar di bawah lipatan halaman Clincoo dengan loading lazy, tanpa menunda gambar hero yang langsung terlihat.","x":"Semua gambar yang diunduh bersamaan memperlambat judul. Di editor.clincoo.buzz gambar di bawah lipatan boleh loading=\"lazy\". Gambar pertama yang terlihat tidak. Bedakan hero dan sisanya Hero, logo, dan gambar di layar pertama tidak memakai lazy. Gambar galeri, kartu bawah, dan ilustrasi footer memakai loading=\"lazy\". Width dan height tetap diisi supaya kotak tidak melompat saat gambar masuk. Jangan lazy pada gambar LCP Gambar terbesar di layar pertama yang ditunda akan terlambat tercatat. Kalau ragu, biarkan bawaan browser untuk satu gambar atas saja. Cek di preview Di app.clincoo.buzz buka panel jaringan, muat ulang, dan gulir. Gambar bawah baru terunduh setelah mendekat. Simpan cek ini di blog.clincoo.buzz ."},{"i":"seo-url-huruf-kecil-tanpa-parameter","c":"seo","cn":"SEO On-Page","t":"Cara Jaga URL Publik Huruf Kecil tanpa Parameter Pelacak","d":"Tata cara menormalkan URL halaman Clincoo ke huruf kecil dan tanpa utm, supaya mesin telusur tidak melihat duplikat halaman yang sama.","x":"URL /Harga dan /harga?utm=x sering dianggap dua halaman. Di editor.clincoo.buzz tautan internal memakai huruf kecil, tanda hubung, dan tanpa parameter pelacak. Satu bentuk kanonis Pilih /harga/ atau /harga, lalu pakai bentuk itu di semua tautan dan canonical. Jangan campur huruf besar di menu. Parameter utm boleh pada tautan kampanye keluar, bukan pada href internal. Canonical menunjuk bentuk bersih Jika pengunjung datang dengan query pelacak, canonical tetap ke URL tanpa query. Jangan menaruh utm di canonical. Cek di preview Di app.clincoo.buzz klik menu dan baca href. Semuanya huruf kecil dan tanpa query. Contoh pola ada di blog.clincoo.buzz ."},{"i":"seo-breadcrumb-yang-bisa-diikuti","c":"seo","cn":"SEO On-Page","t":"Cara Pasang Breadcrumb yang Bisa Diikuti","d":"Tata cara menulis jejak tautan Clincoo dengan nav dan daftar, bukan teks polos, supaya jalur kategori ke artikel bisa diikuti.","x":"Teks “Beranda / SEO / artikel” tanpa tautan tidak bisa diikuti. Di editor.clincoo.buzz bungkus jejak dengan nav dan ol. Tautan sampai induk, bukan halaman ini Butir beranda dan kategori adalah tautan. Butir terakhir adalah teks halaman ini, bukan tautan ke dirinya sendiri. Beri nav aria-label=\"Jejak halaman\". Jangan hanya andalkan skrip Jejak harus ada di HTML awal. JSON-LD boleh menambahkan, tetapi tidak mengganti tautan yang terlihat. Href relatif harus tetap benar setelah pindah folder. Cek di preview Di app.clincoo.buzz klik tiap butir kecuali yang terakhir. Kategori terbuka, bukan 404. Simpan contoh di blog.clincoo.buzz ."},{"i":"seo-cek-tautan-404-sebelum-deploy","c":"seo","cn":"SEO On-Page","t":"Cara Cek Tautan Internal 404 sebelum Deploy","d":"Tata cara menguji tautan internal halaman Clincoo sebelum deploy supaya href yang salah tidak ikut terbit sebagai 404.","x":"Tautan ke file yang sudah diganti nama tetap terlihat biru, tetapi berakhir 404. Di editor.clincoo.buzz kumpulkan href internal lalu buka satu per satu di preview sebelum deploy. Pisahkan internal dan luar Href yang diawali / atau tanpa protokol adalah milik situs. Href https ke domain lain dicatat terpisah. Jangan menganggap tautan luar yang gagal sebagai bug deploy. Cocokkan folder dan huruf index.html di folder lain butuh path yang benar. Huruf besar yang beda satu karakter sudah cukup untuk 404 di hosting yang peka huruf. Trailing slash harus sama dengan canonical. Cek di preview Di app.clincoo.buzz klik tiap tautan utama. Status 200 sebelum tombol deploy. Catat daftar cek di blog.clincoo.buzz ."},{"i":"console-baca-error-pertama-bukan-ikutannya","c":"console","cn":"Konsol","t":"Cara Baca Error Pertama di Konsol, Bukan yang Mengikutinya","d":"Tata cara menemukan error pertama di konsol browser saat halaman Clincoo gagal, lalu mengabaikan error ikutannya yang hanya muncul karena skrip di bawahnya tidak jalan.","x":"Konsol sering menumpuk error setelah error pertama. Di editor.clincoo.buzz gulir ke entri paling atas pada muatan yang gagal, bukan ke baris merah terakhir. Bersihkan konsol, lalu ulangi Kosongkan konsol, muat ulang sekali, dan jangan klik dulu. Error yang muncul sebelum interaksi adalah kandidat pertama. Error setelah klik dicatat terpisah. Abaikan akibat, catat penyebab Pesan 'X is not defined' di bawah sering akibat skrip di atas gagal di-parse. Salin pesan dan file:baris error pertama. Cek preview di app.clincoo.buzz setelah satu perbaikan saja. Jangan menempel seluruh log Kirim error pertama plus satu stack. Log berulang hanya memperpanjang jawaban. Simpan pola ini di blog.clincoo.buzz ."},{"i":"console-preserve-log-saat-navigasi","c":"console","cn":"Konsol","t":"Cara Aktifkan Preserve Log Saat Halaman Pindah","d":"Tata cara menyalakan Preserve log di konsol supaya error saat pindah halaman atau muat ulang di Clincoo tidak hilang sebelum sempat disalin.","x":"Error yang muncul tepat sebelum halaman pindah sering hilang karena konsol ikut dibersihkan. Di editor.clincoo.buzz buka konsol, lalu aktifkan Preserve log sebelum mengulang aksi yang gagal. Nyalakan sebelum mengulang Centang Preserve log, kosongkan konsol sekali, lalu picu ulang alur yang pindah halaman. Entri lama tetap ada sehingga error pertama masih terlihat. Bedakan muatan lama dan baru Setelah navigasi, catatan dari dokumen sebelumnya tetap tercampur. Catat URL dan waktu, lalu bandingkan dengan preview di app.clincoo.buzz setelah satu perubahan saja. Matikan lagi setelah selesai Preserve log yang terus nyala membuat log sesi lama mengganggu debug berikutnya. Matikan setelah kasus tertutup, lalu simpan langkahnya di blog.clincoo.buzz ."},{"i":"console-tampilkan-timestamp-log","c":"console","cn":"Konsol","t":"Cara Nyalakan Timestamp di Setiap Baris Konsol","d":"Tata cara menampilkan jam di tiap log konsol supaya urutan kejadian di halaman Clincoo bisa dicocokkan dengan klik dan respons jaringan.","x":"Tanpa jam, dua log yang berdekatan terlihat seperti terjadi bersamaan. Di editor.clincoo.buzz buka setelan konsol dan nyalakan Show timestamps sebelum mengulang skenario. Cocokkan dengan klik Ulangi satu aksi saja, lalu baca selisih detik antara log klik dan log gagal. Selisih besar berarti proses lain menyela, bukan baris yang sedang kamu curigai. Jangan andalkan urutan visual saja Log async bisa tercetak setelah await selesai. Timestamp membantu memisahkan janji yang lambat dari error parse. Cek hasil di app.clincoo.buzz . Salin jam bersama pesan Saat minta bantuan, sertakan jam dan pesan, bukan tangkapan layar terpotong. Pola ini dicatat di blog.clincoo.buzz ."},{"i":"console-salin-objek-dengan-copy","c":"console","cn":"Konsol","t":"Cara Salin Objek dari Konsol dengan copy()","d":"Tata cara menyalin objek atau array dari konsol ke papan klip tanpa tangkapan layar, supaya data debug Clincoo utuh saat dibagikan.","x":"Tangkapan layar memotong objek bersarang dan tidak bisa ditempel sebagai data. Di editor.clincoo.buzz log objeknya, lalu jalankan copy() pada referensi yang sama. Simpan referensi dulu Tulis const dump = objek di konsol, lalu copy(dump). Fungsi copy menulis JSON atau string ke papan klip. Jangan salin [object Object] dari templat string. Potong data rahasia Hapus token, surel, dan id pengguna sebelum menempel. Preview di app.clincoo.buzz cukup untuk memastikan bentuk data, bukan isi produksi. Tempel sebagai teks Tempel hasil copy ke catatan, bukan gambar. Langkah ini dirangkum di blog.clincoo.buzz ."},{"i":"console-groupcollapsed-detail-opsional","c":"console","cn":"Konsol","t":"Cara Pakai groupCollapsed untuk Detail Opsional","d":"Tata cara mengelompokkan log panjang dengan console.groupCollapsed supaya konsol Clincoo tetap ringkas dan detail hanya dibuka saat dibutuhkan.","x":"Sepuluh baris log untuk satu aksi membuat error lain tenggelam. Di editor.clincoo.buzz bungkus detail dengan console.groupCollapsed dan tutup dengan console.groupEnd. Judul yang bisa difilter Beri judul stabil, misalnya checkout:payload. Filter konsol memakai judul itu. Isi grup hanya state yang relevan, bukan seluruh window. Jangan lupa groupEnd Tanpa groupEnd, log berikutnya masuk grup yang sama. Tutup grup di jalur sukses dan gagal. Uji di app.clincoo.buzz . Lepas sebelum rilis Grup debug bukan pesan pengguna. Hapus atau pagar saat build produksi. Catatan pola ada di blog.clincoo.buzz ."},{"i":"console-kirim-objek-error-utuh","c":"console","cn":"Konsol","t":"Cara Kirim Objek Error Utuh, Bukan String Saja","d":"Tata cara mencatat objek Error di konsol Clincoo supaya stack dan nama error ikut terbawa, bukan hanya kalimat yang kamu tulis sendiri.","x":"console.error('gagal') menyembunyikan stack asli. Di editor.clincoo.buzz teruskan objek error sebagai argumen terpisah: console.error('gagal simpan', err). Jangan gabung jadi string err + '' atau template string hanya menyisakan pesan. Argumen kedua membuat konsol menampilkan nama, pesan, dan stack yang bisa dilacak. Tangkap lalu lempar ulang bila perlu Di catch, catat err dulu, perbaiki state UI, lalu lempar ulang jika pemanggil harus tahu. Cek preview di app.clincoo.buzz setelah satu jalur saja. Satu error, satu konteks Sertakan aksi pengguna, bukan seluruh state. Ringkas pola ini di blog.clincoo.buzz ."},{"i":"console-logpoint-tanpa-jeda","c":"console","cn":"Konsol","t":"Cara Pasang Logpoint Tanpa Menghentikan Skrip","d":"Tata cara memasang logpoint di DevTools Clincoo supaya nilai variabel tercatat di konsol tanpa breakpoint yang menghentikan halaman.","x":"Breakpoint menghentikan timer, animasi, dan fetch. Kalau kamu hanya ingin nilai sebuah variabel, di editor.clincoo.buzz pakai logpoint, bukan breakpoint biru. Klik kanan nomor baris Di panel Sources, klik kanan nomor baris lalu pilih Add logpoint. Isi ekspresi seperti nama, jumlah, dan status. Pesan muncul di konsol saat baris itu lewat, dan skrip tetap jalan. Jangan log seluruh objek besar Ekspresi logpoint dijalankan di halaman. Menulis objek DOM atau array ribuan item memperlambat preview. Pilih satu atau dua field. Hapus logpoint sebelum deploy. Cocokkan dengan preview Buka app.clincoo.buzz , ulangi klik yang memicu baris itu, lalu baca konsol. Kalau tidak ada baris baru, ekspresinya salah atau baris itu tidak pernah tercapai."},{"i":"console-dollar-nol-elemen-terpilih","c":"console","cn":"Konsol","t":"Cara Pakai $0 untuk Elemen yang Sedang Dipilih","d":"Tata cara memakai $0 di konsol Clincoo supaya elemen yang diklik di panel Elements bisa diukur dan diubah tanpa mencari selector dulu.","x":"Menyalin selector panjang sering salah elemen. Di editor.clincoo.buzz pilih elemen di panel Elements, lalu ketik $0 di konsol. Ukur sebelum mengubah $0.getBoundingClientRect() memberi posisi dan ukuran. getComputedStyle($0).display memberi display yang menang. Jangan menebak flex atau block dari tampilan saja. Ubah sementara, lalu tulis di sumber $0.style.outline = '2px solid red' hanya hidup di sesi ini. Muat ulang menghapusnya. Kalau percobaan berhasil, salin perubahannya ke file CSS, bukan meninggalkan perintah konsol. Cek di lebar ponsel Di app.clincoo.buzz aktifkan device toolbar, pilih elemen yang tumpang-tindih, lalu bandingkan $0 dengan elemen di bawahnya lewat $0.parentElement."},{"i":"console-await-promise-yang-ditolak","c":"console","cn":"Konsol","t":"Cara Await Promise yang Ditolak di Konsol","d":"Tata cara menunggu fetch yang gagal di konsol Clincoo supaya alasan penolakan dan status HTTP terbaca, bukan hanya Uncaught (in promise).","x":"Baris Uncaught (in promise) tidak menyebut URL. Di konsol editor.clincoo.buzz kamu bisa mengetik await karena konteksnya async. Tangkap alasan, jangan hanya status await fetch('/api/health').then(r => { if (!r.ok) throw new Error(r.status + ' ' + r.url); return r.json() }) menampilkan status dan URL. Kalau server mengirim teks, baca await res.text() sebelum menganggapnya JSON. Lihat alasan di objek, bukan string Kalau promise ditolak dengan Error, salin error itu. String 'gagal' menghilangkan stack. Untuk penolakan tanpa catch di halaman, buka baris merah lalu klik sumbernya. Ulangi di preview Di app.clincoo.buzz buka Network bersamaan. Status 401, 404, atau CORS harus cocok dengan alasan yang kamu catat. Jangan menempel hanya kata Uncaught."},{"i":"console-breakpoint-kondisi-di-loop","c":"console","cn":"Konsol","t":"Cara Pasang Breakpoint Bersyarat di Dalam Loop","d":"Tata cara menghentikan loop Clincoo hanya saat indeks atau id tertentu, supaya kamu tidak menekan lanjut ratusan kali di DevTools.","x":"Breakpoint di dalam forEach berhenti di setiap item. Di editor.clincoo.buzz klik kanan nomor baris, pilih Add conditional breakpoint. Syarat yang sempit Contoh syarat: item.id === 'paket-bisnis' atau index === 12. Syarat yang selalu benar sama dengan breakpoint biasa. Syarat yang memakai DOM query di loop besar membuat halaman terasa macet. Catat nilai, lalu lanjut Saat berhenti, lihat Scope, bukan hanya baris kode. Salin id dan field yang salah. Hapus breakpoint setelah bug ketemu supaya preview tidak tertahan lagi. Cek ulang tanpa debugger Muat ulang app.clincoo.buzz dengan breakpoint mati. Perbaikan yang hanya terlihat saat skrip dijeda sering salah karena timer dan fetch ikut tertahan."},{"i":"console-filter-level-error-saja","c":"console","cn":"Konsol","t":"Cara Saring Konsol Hanya Level Error","d":"Tata cara menampilkan hanya level error di konsol Clincoo supaya peringatan pihak ketiga tidak menutup pesan yang benar-benar menghentikan halaman.","x":"Konsol penuh log info membuat error merah tenggelam. Di editor.clincoo.buzz klik filter level, lalu sisakan Errors. Matikan info dan verbose dulu Default sering menampilkan Info, Warnings, dan Errors. Untuk pencarian pertama, sisakan Errors. Setelah penyebab ketemu, nyalakan lagi Warnings karena ada peringatan CORS dan cookie yang penting. Kotak teks menyaring isi, bukan level Mengetik nama file di kotak filter menyembunyikan error lain. Kosongkan kotak teks sebelum menyimpulkan tidak ada error. Ikon sidebar error tetap menghitung pesan yang tersembunyi. Samakan dengan preview Ulangi di app.clincoo.buzz pada jendela bersih tanpa ekstensi. Error yang hanya muncul bersama ekstensi bukan bug halaman. Catat satu pesan error pertama."},{"i":"console-table-untuk-bandingkan-baris","c":"console","cn":"Konsol","t":"Cara Bandingkan Baris Data dengan console.table","d":"Tata cara menampilkan array objek Clincoo sebagai tabel di konsol supaya kolom yang beda langsung terlihat, tanpa menggulir objek satu per satu.","x":"Objek bersarang di konsol sulit dibandingkan. Di editor.clincoo.buzz panggil console.table pada array hasil fetch atau daftar blok, bukan console.log berulang. Pilih kolom yang memang dibandingkan Argumen kedua console.table menerima daftar nama properti. Sertakan id, status, dan judul saja supaya kolom acak tidak menutupi perbedaan. Jangan tabelkan objek terlalu dalam Tabel meratakan satu tingkat. Kalau nilai masih objek, petakan dulu ke string singkat. Cek hasil di pratinjau app.clincoo.buzz sebelum mengubah data asli. Salin tabel, bukan tangkapan layar Klik kanan baris tabel lalu salin objek. Tempel ke catatan di blog.clincoo.buzz supaya angka tidak hilang saat gambar diperkecil."},{"i":"prompt-tempel-pesan-error-utuh","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Tempel Pesan Error Utuh saat Minta Bantuan AI","d":"Tata cara menempel pesan error konsol utuh ke asisten AI Clincoo, bukan ringkasan, supaya penyebab baris dan stack tidak hilang.","x":"Ringkasan seperti \"CSS rusak\" membuat jawaban menebak. Pesan error utuh menyebut file, baris, dan jenis kesalahan. Di editor.clincoo.buzz salin dari konsol, jangan mengetik ulang dari ingatan. Salin teks, bukan tangkapan layar saja Teks error bisa dicari dan dikutip. Tangkapan layar membantu untuk tata letak, tetapi stack trace yang terpotong tidak bisa dicek ulang. Sertakan baris pertama pesan dan dua frame stack teratas. Sebut apa yang baru berubah Tambahkan satu kalimat: yang terakhir diubah, browser, dan apakah error muncul saat muat atau saat klik. Jangan tempel seluruh repo. Potongan yang memicu error sudah cukup. Cek jawaban sebelum ditempel balik Di app.clincoo.buzz jalankan ulang langkah yang tadi gagal. Jika pesan error berubah, tempel pesan baru, jangan lanjut dari jawaban lama. Simpan pola pertanyaan yang berhasil di blog.clincoo.buzz ."},{"i":"prompt-kirim-cuplikan-minimal-yang-gagal","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Kirim Cuplikan Minimal yang Masih Gagal","d":"Tata cara memangkas cuplikan HTML, CSS, atau JS Clincoo sampai masih gagal, lalu mengirim itu ke asisten AI supaya jawaban tidak melebar.","x":"Cuplikan sepanjang halaman mengajak jawaban yang ikut panjang. Versi minimal yang masih gagal menunjukkan penyebab. Di editor.clincoo.buzz duplikat bagian yang rusak, lalu hapus yang tidak mengubah gejala. Hapus sampai gejala hilang, lalu kembalikan satu lapis Buang skrip, kelas, dan elemen yang tidak ikut. Jika setelah dihapus gejala hilang, bagian itu terlibat. Kembalikan seperlunya sampai gagal lagi. Itulah cuplikan yang dikirim. Sertakan hasil yang diharapkan Tulis satu kalimat hasil yang kamu mau: tombol sejajar, form tidak terkirim dua kali, atau gambar tidak melompat. Tanpa hasil yang diharapkan, jawaban hanya merapikan kode. Cek di preview Di app.clincoo.buzz tempel jawaban ke salinan, bukan ke halaman produksi. Jika cuplikan minimal sudah beres tetapi halaman asli belum, selisihnya ada di kode yang tadi dibuang. Catat selisih itu di blog.clincoo.buzz ."},{"i":"prompt-minta-langkah-uji-bukan-kode-jadi","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Minta Langkah Uji, Bukan Kode Jadi","d":"Tata cara meminta asisten AI Clincoo menjelaskan langkah cek saat stuck, supaya kamu yang memutuskan perubahan dan tidak menempel kode yang tidak dipahami.","x":"Kode jadi yang langsung ditempel sering memperbaiki gejala dan merusak yang lain. Minta urutan cek dulu. Di editor.clincoo.buzz tulis apa yang sudah dicoba dan apa yang belum. Minta hipotesis, lalu cara membantahnya Contoh permintaan: sebut dua penyebab paling mungkin, dan satu cek di DevTools untuk masing-masing. Jangan minta rewrite seluruh file sebelum hipotesis itu lolos. Batasi wilayah jawaban Sebut file atau blok yang boleh diubah. Jika jawaban menyentuh layout, skrip, dan meta sekaligus, minta dipotong. Perubahan kecil lebih mudah dibatalkan. Cek di preview Di app.clincoo.buzz jalankan cek yang disarankan sebelum menempel kode. Jika cek tidak cocok dengan gejala, kirim hasil cek itu, bukan permintaan ulang yang sama. Ringkas langkah yang terbukti di blog.clincoo.buzz ."},{"i":"prompt-sebutkan-browser-dan-langkah-reproduksi","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Sebutkan Browser dan Langkah Reproduksi","d":"Tata cara menulis browser, lebar layar, dan langkah klik saat minta bantuan AI Clincoo, supaya jawaban tidak mengira bug yang hanya muncul di satu lingkungan.","x":"Bug yang hanya muncul di satu browser sering dijawab seolah terjadi di semua. Sebut lingkungan dulu. Di editor.clincoo.buzz catat browser, versi kasar, dan lebar jendela saat gejala terlihat. Tulis langkah yang bisa diulang Nomori tiga sampai lima langkah: buka halaman, isi field, klik kirim. Hindari \"kadang rusak\". Jika hanya gagal setelah refresh atau di lebar ponsel, tulis itu di kalimat pertama. Sertakan yang sudah tidak gagal Sebut satu lingkungan yang masih beres, misalnya desktop lebar atau browser lain. Perbedaan itu mempersempit dugaan lebih cepat daripada tempelan CSS panjang. Cek ulang di preview Di app.clincoo.buzz ulangi langkah yang sama setelah jawaban diterapkan. Jika langkahnya tidak bisa diulang, jawabannya juga tidak bisa diuji. Simpan pola laporan yang berhasil di blog.clincoo.buzz ."},{"i":"prompt-pisahkan-gejala-dari-dugaan","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Pisahkan Gejala dari Dugaan","d":"Tata cara memisahkan apa yang terlihat di halaman Clincoo dari dugaan penyebab saat minta bantuan AI, supaya jawaban tidak terkunci pada hipotesis yang salah.","x":"Kalimat \"Flexbox-nya rusak\" sudah menyimpulkan. AI lalu memperbaiki flex meskipun penyebabnya gambar tanpa ukuran. Di editor.clincoo.buzz tulis yang terlihat dulu, dugaan belakangan. Gejala adalah yang bisa ditunjuk Contoh gejala: tombol turun ke baris baru, form terkirim dua kali, atau konsol menyebut identifier yang tidak ada. Dugaan seperti \"cache\" atau \"Grid\" ditandai terpisah, bukan sebagai fakta. Minta AI menguji dugaan, bukan membelanya Minta satu cek yang bisa menggagalkan dugaanmu. Jika cek tidak cocok, buang dugaan itu. Jawaban yang hanya setuju dengan dugaan awal sering melewatkan penyebab lain. Cek di preview Di app.clincoo.buzz bandingkan gejala sesudah perubahan dengan kalimat gejala semula. Jika gejalanya berganti, kirim gejala baru, jangan menempel dugaan lama. Catat pemisahan yang membantu di blog.clincoo.buzz ."},{"i":"prompt-minta-satu-perubahan-per-balasan","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Minta Satu Perubahan per Balasan","d":"Tata cara meminta asisten AI Clincoo mengubah satu hal per balasan, supaya kamu bisa membatalkan dan tahu perubahan mana yang memperbaiki gejala.","x":"Balasan yang mengganti layout, skrip, dan meta sekaligus sulit dibatalkan. Di editor.clincoo.buzz minta satu perubahan, lalu berhenti untuk uji. Sebut batas file Tulis file atau blok yang boleh disentuh. Jika jawaban keluar dari batas itu, minta dipotong sebelum ditempel. Perubahan di luar batas sering memperbaiki tampilan dan merusak alur lain. Uji sebelum permintaan berikut Setelah satu perubahan, cek gejala semula. Jika belum beres, kirim hasil cek itu. Jangan menumpuk permintaan baru di atas kode yang belum terbukti. Cek di preview Di app.clincoo.buzz simpan salinan sebelum menempel. Jika gejala memburuk, kembalikan salinan itu, bukan meminta AI \"memperbaiki lagi\" di atas kode yang sudah campur. Ringkas batas yang berguna di blog.clincoo.buzz ."},{"i":"prompt-lampirkan-hasil-yang-diharapkan","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Lampirkan Hasil yang Diharapkan","d":"Tata cara menempel cuplikan hasil yang diharapkan, bukan hanya kode yang rusak, saat minta bantuan AI Clincoo supaya jawaban punya sasaran yang jelas.","x":"Kode yang gagal tanpa sasaran membuat jawaban merapikan gaya, bukan menyelesaikan tugas. Di editor.clincoo.buzz tulis satu kalimat hasil, lalu cuplikan pendek yang mendekati hasil itu. Hasil adalah perilaku, bukan selera Contoh: label tetap terhubung ke input, gambar tidak mendorong tombol saat dimuat, atau error form muncul di sebelah field. Hindari \"buat lebih modern\" tanpa perilaku yang bisa dicek. Tandai bagian yang tidak boleh berubah Sebut teks, URL, atau atribut yang harus tetap. AI sering mengganti nama field atau href saat merapikan markup. Batas itu mencegah perbaikan semu. Cek di preview Di app.clincoo.buzz bandingkan halaman dengan kalimat hasil, bukan dengan gaya jawaban. Jika perilaku cocok tetapi ada yang dilarang berubah, kirim selisih itu. Simpan contoh sasaran yang jelas di blog.clincoo.buzz ."},{"i":"prompt-sensor-token-sebelum-menempel","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Sensor Token sebelum Menempel ke AI","d":"Tata cara menghapus token, kunci, cookie, dan data pengguna dari cuplikan sebelum dikirim ke asisten AI Clincoo, tanpa menghilangkan baris yang menunjukkan error.","x":"Cuplikan debug sering memuat rahasia yang tidak diperlukan untuk diagnosis. Di editor.clincoo.buzz sensor dulu, baru tempel. Jangan mengandalkan AI untuk \"mengabaikan\" kunci yang sudah terkirim. Ganti nilai, jangan hapus barisnya Ganti token dengan kata REDACTED dan biarkan nama variabelnya. Baris yang hilang membuat jawaban menebak struktur. Cookie, query berisi email, dan header Authorization ikut disensor. Cek cuplikan sekali lagi Cari pola sk_ , key, bearer, dan password sebelum kirim. Jika error menyebut nilai rahasia, kirim jenis error dan panjang nilai, bukan nilainya. Cek di preview Di app.clincoo.buzz jangan menempel balik jawaban yang mengembalikan token contoh ke kode produksi. Rotasi kunci jika sempat terkirim. Catat daftar yang wajib disensor di blog.clincoo.buzz ."},{"i":"prompt-sebutkan-versi-dan-perintah","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Sebutkan Versi dan Perintah saat Minta Bantuan AI","d":"Tata cara menulis versi dependensi dan perintah yang benar-benar dijalankan saat minta bantuan AI Clincoo, supaya jawaban tidak mengira lingkungan yang berbeda.","x":"Jawaban AI sering meleset karena versi paket dan perintah tidak disebut. Di editor.clincoo.buzz tulis versi yang terpasang dan perintah utuh sebelum menempel error. Salin perintah, jangan parafrase Tempel perintah apa adanya, termasuk flag. 'Saya menjalankan build' tidak sama dengan npm run build. Catat folder kerja jika perintah dijalankan di subfolder. Sertakan versi yang relevan Sebut Node, browser, atau paket yang disebut di error. Jangan kirim seluruh lockfile. Di app.clincoo.buzz cukup nama paket dan versinya. Tandai yang sudah dicoba Tuliskan satu perintah yang sudah dijalankan ulang dan hasilnya. Simpan pola ini di blog.clincoo.buzz supaya permintaan berikutnya tidak mengulang konteks yang sama."},{"i":"prompt-minta-jelaskan-diff-sebelum-terapkan","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Minta Penjelasan Diff sebelum Menerapkan Jawaban AI","d":"Tata cara meminta asisten AI Clincoo menjelaskan apa yang berubah di diff sebelum kode ditempel, supaya perubahan yang tidak diminta ketahuan lebih dulu.","x":"Kode jadi dari AI sering ikut mengubah baris yang tidak rusak. Di editor.clincoo.buzz minta penjelasan diff dulu, baru terapkan bagian yang kamu setujui. Minta daftar baris yang berubah Minta AI menyebut file, baris, dan alasan tiap perubahan. Tolak jawaban yang hanya menempel blok utuh tanpa menyebut apa yang dihapus. Terapkan satu hunk Salin satu perubahan, simpan, lalu cek preview di app.clincoo.buzz . Jika halaman lain ikut bergeser, hentikan dan kirim gejala itu, bukan hunk berikutnya. Tolak perubahan di luar permintaan Jika diff mengganti nama kelas atau merapikan file lain, kembalikan. Catat batas ini di blog.clincoo.buzz agar sesi berikutnya tetap sempit."},{"i":"prompt-batasi-file-yang-terkait","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Batasi Konteks ke File yang Terkait","d":"Tata cara memilih satu atau dua file yang benar-benar terlibat saat minta bantuan AI Clincoo, supaya jawaban tidak merombak bagian proyek yang tidak terkait.","x":"Menempel seluruh proyek membuat AI menebak file yang salah. Di editor.clincoo.buzz kirim file tempat gejala muncul, plus satu file yang ia panggil. Sebut jalur, bukan nama umum Tulis path seperti src/form.js, bukan 'file form'. Jika ada dua file bernama mirip, sebut keduanya dan tandai yang sedang terbuka. Potong bagian yang tidak ikut jalan Hapus fungsi yang tidak terpanggil dari cuplikan, tetapi jangan menghapus impor yang error sebut. Cek hasilnya di app.clincoo.buzz setelah satu suntingan. Jangan kirim rahasia bersama path Path boleh dikirim. Isi .env tidak. Simpan aturan batas file di blog.clincoo.buzz ."},{"i":"prompt-minta-cek-regresi-setelah-perbaikan","c":"prompt","cn":"Minta Bantuan AI","t":"Cara Minta Cek Regresi setelah Perbaikan AI","d":"Tata cara meminta asisten AI Clincoo menyebut apa yang harus diuji ulang setelah perbaikan, supaya bug yang hilang tidak merusak alur yang tadi berjalan.","x":"Perbaikan yang hanya menutup error konsol bisa merusak alur lain. Di editor.clincoo.buzz minta daftar cek regresi sebelum kamu menutup tugas. Minta tiga jalur, bukan satu Minta jalur yang rusak, jalur tetangga yang memakai fungsi yang sama, dan jalur kosong (tanpa data). Jangan menerima jawaban 'sudah beres' tanpa langkah klik. Uji di lebar yang disebut Jika bug ada di mobile, uji lagi lebar itu di app.clincoo.buzz . Catat satu kalimat hasil: lolos atau masih gagal di langkah ke berapa. Simpan daftar uji Tempel daftar uji singkat di catatan rilis atau di blog.clincoo.buzz . Permintaan AI berikutnya bisa merujuk daftar itu, bukan mengulang dari nol."},{"i":"keyboard-jangan-hapus-outline-tanpa-pengganti","c":"keyboard","cn":"Keyboard","t":"Cara Jangan Hapus Outline Fokus tanpa Pengganti","d":"Tata cara menjaga indikator fokus keyboard di Clincoo, bukan menghapus outline lalu hanya mengandalkan klik mouse.","x":"Banyak lembar gaya menulis outline: none pada tombol. Di editor.clincoo.buzz itu membuat pengguna keyboard tidak tahu elemen mana yang aktif. Ganti, jangan dihapus Jika outline bawaan bentrok dengan desain, pakai :focus-visible dengan ring yang kontras, misalnya outline 2px solid. Jangan menaruh outline: none pada :focus tanpa pengganti. Bedakan mouse dan keyboard :focus-visible tampil saat navigasi keyboard, bukan setiap klik mouse. Itu cukup untuk tombol dan tautan. Input teks tetap butuh indikator saat difokus. Cek di preview Di app.clincoo.buzz tekan Tab berulang. Cincin fokus harus terlihat di tiap kontrol, termasuk di atas latar terang."},{"i":"keyboard-urutan-tab-yang-masuk-akal","c":"keyboard","cn":"Keyboard","t":"Cara Atur Urutan Tab yang Masuk Akal","d":"Tata cara menyusun urutan Tab di halaman Clincoo mengikuti alur baca, bukan tabindex positif yang meloncat-loncat.","x":"Tabindex positif memaksa fokus meloncat sebelum isi halaman. Di editor.clincoo.buzz urutan alami dari HTML hampir selalu lebih aman. Ikuti urutan sumber Letakkan kontrol dalam urutan yang sama dengan yang dibaca. Tautan, tombol, dan input sudah bisa ditab. Jangan menambah tabindex=\"1\" atau lebih besar. Sembunyikan yang tidak interaktif Elemen hias tidak perlu tabindex. Panel yang tertutup diberi hidden atau inert supaya Tab tidak masuk ke dalamnya. tabindex=\"-1\" hanya untuk fokus yang dipindahkan skrip. Cek di preview Di app.clincoo.buzz tab dari atas ke bawah. Fokus harus mengikuti judul, lalu form, lalu tombol kirim, tanpa meloncat ke footer lebih dulu."},{"i":"keyboard-fokus-awal-setelah-aksi","c":"keyboard","cn":"Keyboard","t":"Cara Pindahkan Fokus setelah Aksi Selesai","d":"Tata cara memindahkan fokus keyboard di Clincoo setelah simpan, hapus, atau buka panel supaya pengguna tidak tertinggal di tombol yang hilang.","x":"Kalau tombol dihapus dari DOM saat diklik, fokus jatuh ke body. Di editor.clincoo.buzz pindahkan fokus ke tempat berikutnya yang masuk akal. Pilih target yang sudah ada Setelah simpan, fokus boleh tetap di tombol jika tombolnya masih ada. Setelah hapus baris, pindahkan ke baris berikutnya atau ke judul bagian. Target perlu tabindex=\"-1\" jika bukan kontrol. Jangan lompat ke atas diam-diam Jangan memanggil focus() pada heading utama setiap kali. Pengumuman status cukup lewat wilayah live. Pindahkan fokus hanya jika elemen lama hilang atau panel baru terbuka. Cek di preview Di app.clincoo.buzz hapus item dengan keyboard. Fokus berikutnya harus masih di daftar, bukan hilang ke awal halaman."},{"i":"keyboard-escape-menutup-panel","c":"keyboard","cn":"Keyboard","t":"Cara Tutup Panel dengan Escape","d":"Tata cara menutup menu atau panel Clincoo dengan tombol Escape lalu mengembalikan fokus ke pemicu.","x":"Panel yang hanya tertutup lewat klik luar menyulitkan keyboard. Di editor.clincoo.buzz Escape harus menutup panel dan mengembalikan fokus. Dengarkan Escape di panel Pada keydown, jika event.key adalah Escape, cegah default hanya jika panel memang terbuka. Tutup panel, set aria-expanded ke false, lalu focus() ke tombol pemicu. Jangan makan Escape milik browser Jika panel sudah tertutup, jangan memanggil preventDefault. Dialog bawaan sudah menutup sendiri dengan Escape. Jangan memasang listener ganda yang berebut. Cek di preview Di app.clincoo.buzz buka menu dengan Enter, lalu tekan Escape. Panel hilang dan fokus kembali ke tombol yang membukanya."},{"i":"keyboard-shortcut-jangan-tabrak-browser","c":"keyboard","cn":"Keyboard","t":"Cara Hindari Shortcut yang Menabrak Browser","d":"Tata cara menambah pintasan keyboard di Clincoo tanpa merebut Ctrl+S, Ctrl+T, atau pintasan pembaca layar.","x":"Shortcut kustom yang memanggil preventDefault pada kombinasi umum membuat tab browser atau simpan halaman tidak jalan. Di editor.clincoo.buzz pilih kombinasi yang longgar. Hindari kombinasi yang sudah dipakai Jangan merebut Ctrl+T, Ctrl+W, Ctrl+L, atau Ctrl+S. Akseskey satu huruf juga mudah bentrok. Jika perlu pintasan, pakai pola yang jarang dan tampilkan petunjuk di UI, bukan hanya di kode. Batasi saat fokus di input Jangan menjalankan shortcut huruf saat pengguna mengetik di input atau textarea. Cek event.target sebelum preventDefault. Pengguna harus tetap bisa mengetik. Cek di preview Di app.clincoo.buzz coba Ctrl+S dan ketik di field. Perilaku browser dan ketikan harus tetap utuh. Pintasanmu hanya jalan di konteks yang kamu dokumentasikan, termasuk catatan di blog.clincoo.buzz ."},{"i":"keyboard-skip-link-ke-main","c":"keyboard","cn":"Keyboard","t":"Cara Tambah Skip Link ke Konten Utama","d":"Tata cara memasang tautan lewati ke main di halaman Clincoo supaya pengguna keyboard tidak men-Tab seluruh header setiap kali.","x":"Header yang panjang memaksa Tab berulang sebelum sampai ke isi. Di editor.clincoo.buzz tautan lewati adalah kontrol pertama di body, tersembunyi sampai fokus. Letakkan sebelum navigasi Tautan href=\"#isi-utama\" menuju elemen main yang punya id sama. Jangan mengarah ke div kosong. main perlu tabindex=\"-1\" hanya jika fokus harus pindah ke wilayah itu, bukan ke kontrol di dalamnya. Sembunyikan tanpa menghapus dari Tab Pakai CSS yang menggeser tautan keluar layar, lalu tampilkan saat :focus. Jangan display:none atau visibility:hidden, karena Tab tidak akan menemukannya. Teksnya jelas: Loncat ke isi. Cek di preview Di app.clincoo.buzz tekan Tab sekali saat halaman dimuat. Tautan lewati harus muncul, Enter memindahkan fokus ke main, dan header tidak diulang. Catat polanya di blog.clincoo.buzz jika tim memakai header yang sama di setiap halaman."},{"i":"keyboard-panah-di-menu","c":"keyboard","cn":"Keyboard","t":"Cara Gerakkan Menu dengan Tombol Panah","d":"Tata cara memakai tombol panah di menu Clincoo, sementara Tab tetap keluar dari menu, bukan berhenti di setiap butir.","x":"Menu yang setiap butirnya bisa di-Tab membuat daftar panjang. Di editor.clincoo.buzz pola menu memakai satu tab stop, lalu panah memindahkan pilihan. Satu tab stop, lalu panah Tombol pemicu tetap di urutan Tab. Setelah terbuka, butir menu memakai tabindex=\"-1\" kecuali butir yang aktif. Panah bawah dan atas memindahkan tabindex 0 ke saudara berikutnya, lalu memanggil focus(). Home, End, dan Escape Home ke butir pertama, End ke butir terakhir. Escape menutup menu dan mengembalikan fokus ke pemicu. Tab boleh menutup menu lalu melanjutkan ke kontrol berikutnya, bukan masuk ke setiap butir. Cek di preview Di app.clincoo.buzz buka menu dengan Enter, gerakkan panah, lalu Tab keluar. Fokus tidak boleh terjebak di butir terakhir. Ulangi di lebar ponsel karena menu yang menutupi layar sering menelan panah."},{"i":"keyboard-enter-dan-space-pada-tombol","c":"keyboard","cn":"Keyboard","t":"Cara Bedakan Enter dan Space pada Tombol","d":"Tata cara menangani Enter dan Space di tombol Clincoo supaya aksi tidak terpicu dua kali dan tautan tidak ikut terpencet.","x":"Tombol bawaan sudah aktif lewat Enter dan Space. Di editor.clincoo.buzz listener click tambahan pada keydown sering menggandakan aksi. Andalkan click bawaan Untuk button type=\"button\", cukup dengarkan click. Browser mengirim click saat Enter atau Space dilepas. Jangan menambah keydown yang juga memanggil handler yang sama. Cegah Space menggulir halaman Jika kamu membangun kontrol sendiri, Space harus preventDefault saat keydown supaya halaman tidak tergulir, lalu jalankan aksi pada keyup. Enter menjalankan aksi pada keydown. Jangan memasang pola ini pada a href. Cek di preview Di app.clincoo.buzz tab ke tombol Simpan, tekan Space, lalu Enter. Aksi harus sekali masing-masing, dan halaman tidak meloncat. Jika tombol ada di dalam tautan, pisahkan dulu: tautan untuk pindah URL, tombol untuk aksi."},{"i":"keyboard-jebak-fokus-modal-kustom","c":"keyboard","cn":"Keyboard","t":"Cara Jebak Fokus di Modal Kustom","d":"Tata cara menahan Tab di dalam modal kustom Clincoo jika kamu belum memakai dialog.showModal, lalu mengembalikan fokus saat tutup.","x":"Modal dari div fixed tidak menahan Tab. Di editor.clincoo.buzz lebih baik memakai dialog dan showModal. Kalau modal lama belum diganti, jebak fokus sendiri. Simpan pemicu, lalu kunci Tab Saat membuka, simpan document.activeElement. Kumpulkan kontrol yang terlihat di dalam panel. Pada keydown Tab di kontrol terakhir, preventDefault dan fokus ke kontrol pertama. Shift+Tab di kontrol pertama kembali ke yang terakhir. Jangan jebak yang tersembunyi Abaikan tombol dengan hidden, disabled, atau display none. Setelah tutup, hapus listener dan focus() ke pemicu. Escape tetap menutup, kecuali dialog konfirmasi berbahaya yang memang harus lewat tombol. Cek di preview Di app.clincoo.buzz buka modal, Tab berkali-kali, lalu Shift+Tab. Fokus tidak boleh masuk ke footer di belakang. Tutup modal dan pastikan fokus kembali ke tombol yang membukanya."},{"i":"keyboard-jangan-pakai-accesskey-satu-huruf","c":"keyboard","cn":"Keyboard","t":"Cara Jangan Pasang accesskey Satu Huruf","d":"Tata cara menghindari accesskey satu huruf di halaman Clincoo supaya pintasan tidak menabrak menu browser atau pembaca layar.","x":"accesskey satu huruf terlihat singkat, tetapi kombinasinya beda di setiap browser dan sering merebut pintasan yang sudah ada. Di editor.clincoo.buzz hindari accesskey satu huruf. Jangan andalkan accesskey Tombol yang penting harus bisa dicapai lewat Tab dan punya nama terlihat. Jika perlu pintasan, tampilkan petunjuk di UI dan batasi pada konteks yang tidak sedang mengetik. Jangan preventDefault pada huruf biasa di input. Bentrok yang sering terjadi Huruf tunggal mudah bentrok dengan navigasi pembaca layar dan menu browser. Alt+huruf di satu peramban menjadi Alt+Shift di peramban lain. Pengguna tidak bisa menghafal perbedaan itu. Cek di preview Di app.clincoo.buzz tab ke kontrol utama tanpa menekan accesskey. Lalu ketik di input: huruf tidak boleh memicu aksi tersembunyi. Dokumentasikan pintasan yang memang kamu buat di blog.clincoo.buzz , bukan di atribut accesskey."},{"i":"keyboard-kembalikan-fokus-setelah-elemen-hilang","c":"keyboard","cn":"Keyboard","t":"Cara Kembalikan Fokus setelah Elemen Hilang","d":"Tata cara mengembalikan fokus keyboard di Clincoo setelah tombol atau panel yang sedang fokus dihapus, supaya Tab tidak jatuh ke body.","x":"Kalau elemen yang sedang fokus dihapus, browser sering melempar fokus ke body. Pengguna keyboard harus men-Tab dari atas lagi. Di editor.clincoo.buzz simpan pemicu sebelum menutup panel. Simpan pemicu sebelum menutup Sebelum remove() atau hidden, catat document.activeElement. Setelah panel hilang, panggil focus() pada tombol yang tadi membuka panel. Jangan focus() ke elemen yang sudah tidak ada di dokumen. Jangan andalkan urutan Tab otomatis Tanpa pengembalian fokus, Tab berikutnya mulai dari body atau dari kontrol tak terduga. Di dialog asli, showModal mengembalikan fokus sendiri. Panel kustom harus mengembalikannya manual. Cek di preview Di app.clincoo.buzz buka panel hanya dengan keyboard, lalu tutup. Fokus harus kembali ke tombol buka, bukan ke awal halaman. Catat polanya di blog.clincoo.buzz jika panel dipakai di lebih dari satu template."},{"i":"keyboard-jangan-autofocus-di-tiap-muat","c":"keyboard","cn":"Keyboard","t":"Cara Jangan Pakai autofocus di Setiap Muat Halaman","d":"Tata cara membatasi autofocus di halaman Clincoo supaya pengguna keyboard dan pembaca layar tidak langsung ditarik ke isian saat halaman dibuka.","x":"autofocus memindahkan fokus begitu dokumen siap. Di halaman yang sering dibuka, itu memotong skip link dan menu. Di editor.clincoo.buzz jangan pasang autofocus pada setiap template. Kapan autofocus masuk akal Satu isian utama di halaman khusus, misalnya kotak cari yang memang tujuan halaman, boleh memakai autofocus. Halaman artikel, dashboard, dan form panjang tidak. Yang rusak kalau selalu dipasang Skip link tidak pernah jadi perhentian pertama. Pembaca layar langsung mengumumkan isian, bukan judul halaman. Pengguna yang hanya ingin baca harus keluar dari isian dulu. Cek di preview Di app.clincoo.buzz muat halaman dan tekan Tab sekali. Perhentian pertama harus skip link atau kontrol header, bukan input tersembunyi. Jika satu halaman memang butuh fokus awal, tulis alasannya di blog.clincoo.buzz ."},{"i":"aria-label-pada-tombol-ikon","c":"aria","cn":"ARIA","t":"Cara Beri aria-label pada Tombol Ikon","d":"Tata cara menamai tombol ikon di situs Clincoo dengan aria-label supaya pembaca layar tidak hanya menyebut tombol kosong.","x":"Ikon tanpa teks terlihat jelas bagi sebagian orang, tetapi tidak punya nama bagi pembaca layar. Di editor.clincoo.buzz tombol ikon wajib punya nama yang bisa diucapkan. Pakai aria-label yang menyebut aksi Tulis aria-label=\"Tutup menu\", bukan aria-label=\"ikon\". Nama harus sama dengan yang akan kamu tulis jika ada teks. Jangan mengulang nama di title saja. Sembunyikan ikon dekoratif SVG di dalam tombol yang sudah punya aria-label diberi aria-hidden=\"true\" supaya tidak dibaca dua kali. Jangan menaruh aria-hidden pada tombolnya sendiri. Cek di preview Di app.clincoo.buzz tab ke tombol ikon. Nama yang diumumkan harus aksi, misalnya tutup atau cari, bukan tombol kosong."},{"i":"aria-live-untuk-pesan-status","c":"aria","cn":"ARIA","t":"Cara Umumkan Pesan Status dengan aria-live","d":"Tata cara memakai aria-live di Clincoo supaya pesan sukses atau gagal diumumkan tanpa memindahkan fokus secara kasar.","x":"Alert yang muncul diam-diam tidak terdengar. Di editor.clincoo.buzz bungkus pesan status dengan wilayah aria-live. Pilih polite untuk status biasa Untuk “Tersimpan” atau “Format email belum benar”, pakai aria-live=\"polite\". Pesan penting yang harus memotong, seperti sesi habis, boleh assertive. Jangan assertive untuk setiap ketikan. Update teks, jangan hanya warna Wilayah live harus sudah ada di halaman sebelum teks diisi, atau teks baru disisipkan ke dalamnya. Mengganti warna border saja tidak cukup. Tulis kalimat lengkap. Cek di preview Di app.clincoo.buzz kirim form uji. Pesan status harus terbaca setelah jeda singkat, dan fokus tetap di tombol kirim kecuali kamu memang memindahkannya."},{"i":"aria-hidden-pada-ikon-dekoratif","c":"aria","cn":"ARIA","t":"Cara Sembunyikan Ikon Dekoratif dengan aria-hidden","d":"Tata cara menandai ikon hias di Clincoo dengan aria-hidden supaya pembaca layar tidak mengucapkan nama file SVG.","x":"Ikon hias di samping judul sering punya nama file seperti icon-star.svg. Di editor.clincoo.buzz ikon yang tidak menambah makna harus disembunyikan dari pohon aksesibilitas. Pasang aria-hidden pada SVG Tambahkan aria-hidden=\"true\" pada elemen svg, bukan pada heading yang membungkusnya. Jika teks di sebelahnya sudah menjelaskan aksi, ikon tidak perlu nama kedua. Jangan sembunyikan kontrol Tombol, tautan, dan input tidak boleh aria-hidden. Kalau ikon adalah satu-satunya isi tombol, beri tombol itu aria-label dan sembunyikan hanya SVG di dalamnya. Cek di preview Di app.clincoo.buzz buka pohon aksesibilitas. Ikon hias tidak muncul sebagai nama terpisah, sedangkan tombol tetap bisa difokus."},{"i":"aria-expanded-pada-menu-dropdown","c":"aria","cn":"ARIA","t":"Cara Set aria-expanded pada Menu Dropdown","d":"Tata cara menyelaraskan aria-expanded dengan panel menu di Clincoo supaya status buka atau tutup terdengar.","x":"Menu yang hanya berubah secara visual membuat pengguna keyboard tidak tahu panelnya terbuka. Di editor.clincoo.buzz tombol pemicu wajib punya aria-expanded. Ikat tombol ke panel Beri tombol aria-controls yang sama dengan id panel. Saat tertutup, aria-expanded=\"false\". Saat terbuka, ganti ke true dalam handler yang sama dengan class tampilan. Tutup dengan Escape Dengarkan Escape pada panel, set aria-expanded kembali ke false, lalu kembalikan fokus ke tombol pemicu. Jangan hanya menyembunyikan panel dengan CSS. Cek di preview Di app.clincoo.buzz buka menu dengan Enter. Pengumuman harus berubah dari tertutup menjadi terbuka, lalu kembali saat Escape."},{"i":"aria-describedby-petunjuk-field","c":"aria","cn":"ARIA","t":"Cara Hubungkan Petunjuk Field dengan aria-describedby","d":"Tata cara menautkan teks bantuan dan pesan error ke input Clincoo dengan aria-describedby.","x":"Placeholder hilang saat pengguna mengetik. Di editor.clincoo.buzz petunjuk format harus tetap ada dan terhubung ke input. Beri id pada paragraf petunjuk Label memakai for yang sama dengan id input. Paragraf bantuan, misalnya “Gunakan minimal 8 karakter”, punya id sendiri. Input menunjuk id itu lewat aria-describedby. Gabungkan error tanpa menghapus petunjuk Saat validasi gagal, tambahkan id pesan error di aria-describedby, dipisah spasi. Jangan mengganti label menjadi kalimat error. Label tetap nama field. Cek di preview Di app.clincoo.buzz fokus ke input. Nama, petunjuk, lalu pesan error harus dibacakan berurutan, bukan hanya placeholder."},{"i":"aria-current-pada-navigasi-aktif","c":"aria","cn":"ARIA","t":"Cara Tandai Halaman Aktif dengan aria-current","d":"Tata cara memakai aria-current pada nav Clincoo supaya tautan halaman yang sedang dibuka diumumkan sebagai current.","x":"Warna tebal pada menu tidak selalu terbaca. Di editor.clincoo.buzz tautan halaman aktif perlu aria-current. Pakai page, bukan true semata Pada tautan dokumen yang sedang dibuka, set aria-current=\"page\". Untuk langkah di dalam satu halaman, aria-current=\"step\" lebih tepat. Hapus atribut dari tautan lain. Jangan hanya andalkan kelas CSS Kelas is-active boleh mengatur warna, tetapi status aksesibel harus atribut. Satu item saja yang current. Jangan menaruh aria-current pada seluruh nav. Cek di preview Di app.clincoo.buzz pindah halaman lalu tab ke menu. Hanya tautan yang cocok dengan URL yang diumumkan sebagai current page."},{"i":"aria-invalid-pada-field-error","c":"aria","cn":"ARIA","t":"Cara Tandai Field Gagal dengan aria-invalid","d":"Tata cara memasang aria-invalid pada input Clincoo setelah validasi gagal, lalu menghapusnya saat nilai sudah benar.","x":"Border merah saja tidak memberi status. Di editor.clincoo.buzz field yang gagal perlu aria-invalid. Set true hanya saat gagal Setelah submit, field kosong atau format salah mendapat aria-invalid=\"true\". Field yang lolos dihapus atributnya, atau di-set false. Jangan menandai semua field sebelum pengguna mencoba. Sertakan pesan teks aria-invalid tidak menggantikan kalimat error. Pasangkan dengan aria-describedby ke elemen yang menjelaskan apa yang harus diperbaiki. Cek di preview Di app.clincoo.buzz kirim form kosong. Field wajib diumumkan invalid, lalu tidak invalid lagi setelah diisi dengan benar."},{"i":"aria-pressed-pada-tombol-toggle","c":"aria","cn":"ARIA","t":"Cara Tandai Tombol Toggle dengan aria-pressed","d":"Tata cara memasang aria-pressed pada tombol nyala-mati di Clincoo supaya pembaca layar mengumumkan status, bukan hanya nama tombol.","x":"Tombol yang mengubah warna saja tidak memberitahu status. Di editor.clincoo.buzz tombol toggle butuh aria-pressed. Pakai button, bukan div Elemennya tetap button. aria-pressed=\"true\" saat aktif dan aria-pressed=\"false\" saat mati. Jangan menulis \"aktif\" hanya di class CSS. Perbarui setelah klik Di handler klik, ubah atribut bersamaan dengan tampilan. Nama tombol tetap singkat, misalnya \"Mode gelap\". Status dibaca dari aria-pressed, bukan dari aria-label yang berubah-ubah. Cek di preview Di app.clincoo.buzz aktifkan toggle lalu tab ke tombol. Pembaca layar harus menyebut ditekan atau tidak ditekan, sesuai nilai terbaru."},{"i":"aria-controls-pada-panel","c":"aria","cn":"ARIA","t":"Cara Hubungkan Tombol ke Panel dengan aria-controls","d":"Tata cara mengikat tombol pembuka panel di Clincoo ke id panel lewat aria-controls supaya hubungan kontrolnya jelas.","x":"Tombol yang membuka panel di bawahnya perlu hubungan yang bisa dibaca mesin. Di editor.clincoo.buzz hubungan itu ditulis dengan aria-controls. Samakan id panel Beri panel id unik, misalnya id=\"panel-bantuan\". Pada tombol tulis aria-controls=\"panel-bantuan\". Nilai harus sama persis dengan id, tanpa tanda pagar. Pasangkan dengan aria-expanded aria-controls tidak menggantikan status buka. Tetap set aria-expanded=\"true\" saat panel terlihat dan false saat disembunyikan. Jangan menghapus panel dari DOM jika id-nya masih dirujuk. Cek di preview Di app.clincoo.buzz buka panel dari tombol. Inspeksi elemen: aria-controls menunjuk id yang benar-benar ada di halaman."},{"i":"aria-haspopup-pada-menu","c":"aria","cn":"ARIA","t":"Cara Tandai Tombol Menu dengan aria-haspopup","d":"Tata cara menandai tombol yang membuka menu di Clincoo dengan aria-haspopup supaya pembaca layar tahu ada popup, bukan navigasi biasa.","x":"Tombol menu sering terlihat sama dengan tautan. Di editor.clincoo.buzz bedanya perlu ditulis di aria-haspopup. Pilih nilai yang sesuai Untuk menu aksi tulis aria-haspopup=\"menu\". Untuk dialog tulis \"dialog\". Untuk daftar saran tulis \"listbox\". Jangan memakai true jika jenis popup-nya sudah jelas. Jangan taruh di tautan halaman aria-haspopup hanya untuk kontrol yang membuka popup di halaman yang sama. Tautan yang pindah ke URL lain tidak perlu atribut ini. Pasangkan dengan aria-expanded pada tombol pembuka. Cek di preview Di blog.clincoo.buzz atau preview app, tab ke tombol menu. Nama plus petunjuk popup harus terdengar sebelum item di dalamnya."},{"i":"role-alert-untuk-pesan-error","c":"aria","cn":"ARIA","t":"Cara Umumkan Error Form dengan role alert","d":"Tata cara menaruh role alert pada pesan gagal di form Clincoo supaya error dibacakan segera, tanpa menunggu pengguna pindah fokus.","x":"Pesan merah yang muncul setelah submit sering terlewat. Di editor.clincoo.buzz pesan itu perlu role=\"alert\". Sisipkan teks, jangan hanya warna Siapkan elemen kosong di dekat form, lalu isi teks error saat validasi gagal. role=\"alert\" setara aria-live=\"assertive\" dan dibaca begitu teks masuk. Jangan menaruh role alert pada setiap field. Satu pesan, lalu fokus Tulis satu kalimat yang menyebut apa yang harus diperbaiki. Setelah itu pindahkan fokus ke field pertama yang gagal. role alert mengumumkan, aria-invalid menandai field-nya. Cek di preview Di app.clincoo.buzz kirim form kosong. Pesan gagal harus terdengar tanpa klik tambahan, dan tidak berulang setiap ketikan."},{"i":"aria-labelledby-pada-dialog","c":"aria","cn":"ARIA","t":"Cara Beri Nama Dialog dengan aria-labelledby","d":"Tata cara menamai dialog Clincoo lewat aria-labelledby yang menunjuk heading terlihat, supaya nama tidak dobel dengan aria-label.","x":"Dialog tanpa nama hanya terdengar sebagai dialog. Di editor.clincoo.buzz nama diambil dari heading yang sudah terlihat. Tunjuk id heading Beri judul id, misalnya id=\"judul-hapus\". Pada dialog tulis aria-labelledby=\"judul-hapus\". Pembaca layar memakai teks heading itu. Jangan menambah aria-label dengan kalimat yang sama. Deskripsi terpisah Kalimat penjelasan boleh dirujuk dengan aria-describedby ke paragraf di dalam dialog. Judul tetap pendek. Jika judul berubah, id-nya jangan ikut berubah. Cek di preview Di app.clincoo.buzz buka dialog konfirmasi. Nama yang diumumkan harus sama dengan heading di layar, bukan \"dialog\" saja."},{"i":"dialog-bukan-div-modal","c":"dialog","cn":"Dialog HTML","t":"Cara Buka Modal dengan dialog, Bukan Div","d":"Tata cara memakai elemen dialog dan showModal di halaman Clincoo supaya fokus terkunci dan Escape menutup modal.","x":"Modal dari div yang di-position fixed sering meninggalkan fokus di belakang layar. Elemen dialog dengan showModal mengunci interaksi ke jendela itu dan menutupnya dengan Escape. Pakai showModal, bukan atribut open saja open membuat dialog terlihat, tetapi tidak selalu menjadi modal. Dari tombol, panggil showModal(). Tutup dengan close() pada tombol Batal, dan dengarkan event close. Jangan buat dua dialog terbuka bersamaan. Beri nama jendela Di editor.clincoo.buzz tambahkan aria-labelledby yang menunjuk ke judul di dalam dialog. Tombol pemicu harus menjelaskan aksi: “Hapus proyek”, bukan ikon tanpa nama. Kembalikan fokus setelah tutup Setelah close, fokus sebaiknya kembali ke tombol yang membuka modal. Cek di preview app.clincoo.buzz selebar ponsel: dialog tidak boleh lebih lebar dari layar, dan latar belakang tidak ikut tergulir."},{"i":"dialog-form-method-dialog","c":"dialog","cn":"Dialog HTML","t":"Cara Kirim Form di dalam dialog dengan method dialog","d":"Tata cara memakai form method dialog di Clincoo supaya submit menutup jendela dan mengirim nilai tanpa memuat ulang halaman.","x":"Form di dalam dialog yang memakai method post sering memuat ulang preview. method dialog menutup jendela dan mengisi returnValue dengan nilai tombol submit, tanpa navigasi. Setel method dialog dan nama tombol Di editor.clincoo.buzz bungkus isian dengan form method=\"dialog\". Tombol Simpan beri name dan value, misalnya name=\"aksi\" value=\"simpan\". Tombol Batal cukup type=\"submit\" dengan value=\"batal\", atau type=\"button\" yang memanggil close(). Baca hasilnya di event close Setelah form terkirim, dialog menutup dan event close terpicu. Baca dialog.returnValue untuk membedakan simpan dan batal. Jangan andalkan input di luar dialog; yang ikut terkirim hanya kontrol sukses di dalam form itu. Cek di preview Di app.clincoo.buzz pastikan Enter di input teks mengirim form, bukan membuka dialog kedua. Jika validasi gagal, panggil preventDefault pada submit dan biarkan dialog tetap terbuka."},{"i":"dialog-tutup-lewat-backdrop","c":"dialog","cn":"Dialog HTML","t":"Cara Tutup dialog saat Klik Backdrop","d":"Tata cara menutup dialog modal Clincoo hanya jika klik jatuh di backdrop, bukan di panel isi.","x":"showModal menampilkan backdrop, tetapi klik di area gelap tidak otomatis memanggil close. Tanpa penanganan, pengguna mengira jendela macet. Bandingkan target klik dengan dialog Pasang listener click pada elemen dialog. Tutup hanya jika event.target adalah dialog itu sendiri. Klik di panel dalam punya target anak, jadi jendela tetap terbuka. Jangan tutup dialog konfirmasi bahaya Di editor.clincoo.buzz dialog hapus proyek sebaiknya tidak tertutup lewat backdrop. Pakai pola ini hanya untuk pratinjau atau pilihan yang bisa dibatalkan. Tombol tutup tetap wajib, karena tidak semua pengguna mengklik area gelap. Uji pointer dan keyboard Di app.clincoo.buzz cek klik, ketuk ponsel, dan Escape. Backdrop klik tidak boleh ikut menekan tombol di halaman belakang."},{"i":"dialog-inert-pada-latar","c":"dialog","cn":"Dialog HTML","t":"Cara Tandai Latar dengan inert saat dialog Terbuka","d":"Tata cara memakai atribut inert pada sisa halaman Clincoo saat dialog modal terbuka supaya Tab tidak kabur ke belakang.","x":"Dialog modal sudah menahan fokus, tetapi konten di luarnya masih bisa ikut terbacakan jika struktur halaman membingungkan. inert mengeluarkan subtree dari fokus, klik, dan pohon aksesibilitas. Pasang inert saat showModal Sebelum showModal, setel inert pada main atau pembungkus aplikasi, bukan pada dialog itu sendiri. Simpan elemen yang tadi fokus. Setelah close, hapus inert dan kembalikan fokus. Jangan inert pada leluhur dialog Jika dialog berada di dalam main, inert pada main ikut membekukan dialog. Di editor.clincoo.buzz letakkan dialog sebagai saudara main, lalu inert hanya pada main. Cek dengan Tab Di preview app.clincoo.buzz tekan Tab berulang. Fokus harus berputar di dalam dialog. Setelah tutup, tombol pemicu harus menerima fokus lagi."},{"i":"dialog-baca-return-value","c":"dialog","cn":"Dialog HTML","t":"Cara Baca returnValue setelah dialog Ditutup","d":"Tata cara mengisi dan membaca returnValue dialog Clincoo supaya pemanggil tahu pilihan pengguna tanpa variabel global.","x":"Menutup dialog dengan close() tanpa nilai membuat pemanggil menebak-nebak. returnValue adalah string hasil yang bisa dibaca setelah event close. Kirim alasan lewat close Tombol Hapus memanggil close(\"hapus\"). Tombol Batal memanggil close(\"batal\") atau close(\"\"). Escape juga menutup modal dan biasanya mengosongkan returnValue, jadi perlakukan string kosong sebagai batal. Dengarkan close, bukan hanya klik Di editor.clincoo.buzz pasang satu listener close pada dialog. Di situ baca returnValue lalu jalankan aksi. Jangan menghapus proyek langsung di onclick sebelum close, karena pengguna masih bisa membatalkan lewat Escape. Kosongkan nilai sebelum dibuka lagi Setel returnValue ke string kosong sebelum showModal berikutnya. Cek di app.clincoo.buzz bahwa membuka ulang dialog tidak mengulang aksi hapus dari nilai lama."},{"i":"dialog-fokus-awal-ke-input","c":"dialog","cn":"Dialog HTML","t":"Cara Pindahkan Fokus ke Input Pertama di dialog","d":"Tata cara mengatur autofokus di dialog Clincoo supaya kursor masuk ke input pertama, bukan ke tombol tutup.","x":"Saat showModal, browser memfokuskan elemen dengan autofocus, atau elemen yang bisa difokus pertama. Jika tombol tutup muncul lebih dulu di DOM, kursor salah tempat. Tandai input, bukan tombol ikon Pasang autofocus pada input nama proyek. Jangan pasang autofocus di dua kontrol. Jika dialog berisi peringatan, fokuskan tombol Batal supaya Enter tidak langsung menghapus. Urutkan DOM dengan masuk akal Di editor.clincoo.buzz letakkan judul, lalu input, lalu tindakan. Tombol tutup boleh tampil di pojok secara visual, tetapi di DOM ia tidak harus menjadi kontrol pertama jika itu mencuri fokus. Uji tanpa tetikus Buka dialog dari app.clincoo.buzz hanya dengan keyboard. Setelah terbuka, mengetik harus langsung mengisi input. Fokus tidak boleh tetap di tombol yang ada di halaman belakang."},{"i":"dialog-tangani-event-cancel","c":"dialog","cn":"Dialog HTML","t":"Cara Tangani Event cancel saat Escape Menutup dialog","d":"Tata cara memakai event cancel di dialog Clincoo supaya Escape bisa dicegah jika form belum disimpan.","x":"Menekan Escape pada dialog modal memicu event cancel sebelum jendela tertutup. Tanpa penangan, isian form di editor bisa hilang meski pengguna hanya ingin tetap di jendela itu. Dengarkan cancel, lalu cegah jika perlu Pasang addEventListener('cancel', ...) pada elemen dialog. Jika ada perubahan yang belum disimpan, panggil preventDefault() supaya dialog tetap terbuka. Jangan cegah Escape pada dialog konfirmasi singkat yang tidak menyimpan data. Bedakan cancel dan close cancel terjadi saat penutupan dibatalkan oleh pengguna, misalnya Escape. close terjadi setelah dialog benar-benar tertutup, termasuk lewat close(). Di editor.clincoo.buzz simpan draf dulu, baru izinkan cancel. Cek di preview Buka preview app.clincoo.buzz , ketik di form, lalu tekan Escape. Dialog harus tetap ada dan fokus tidak loncat ke halaman belakang."},{"i":"dialog-hindari-invalidstateerror","c":"dialog","cn":"Dialog HTML","t":"Cara Hindari InvalidStateError saat showModal Dipanggil Ulang","d":"Tata cara cek dialog.open sebelum showModal di Clincoo supaya klik ganda tidak melempar InvalidStateError.","x":"showModal() hanya boleh dipanggil jika dialog belum terbuka. Klik ganda pada tombol “Hapus” sering memanggilnya dua kali dan browser melempar InvalidStateError. Cek open sebelum membuka Sebelum showModal(), baca properti open. Jika sudah true, jangan panggil lagi. Nonaktifkan tombol pemicu selama dialog terbuka, lalu aktifkan kembali di event close. Jangan bungkus dengan try tanpa pesan try/catch boleh menangkap InvalidStateError, tetapi pengguna tetap perlu tahu kenapa jendela tidak berubah. Di editor.clincoo.buzz tampilkan satu dialog saja, bukan tumpukan modal. Uji klik cepat Di preview app.clincoo.buzz klik tombol pembuka dua kali cepat. Konsol harus bersih dan fokus tetap di dalam dialog."},{"i":"dialog-closedby-light-dismiss","c":"dialog","cn":"Dialog HTML","t":"Cara Pakai closedby supaya dialog Bisa Ditutup Ringan","d":"Tata cara mengatur atribut closedby pada dialog Clincoo supaya klik luar atau tombol tutup mengikuti niat desain.","x":"Tidak semua dialog boleh tertutup hanya karena klik jatuh di luar panel. Atribut closedby memberi isyarat browser apakah dialog boleh light-dismiss. Pilih nilai yang sesuai any mengizinkan penutupan dari luar, closerequest membatasi ke permintaan tutup seperti Escape, dan none menolak penutupan ringan. Dialog hapus data di Clincoo sebaiknya none atau closerequest, lalu sediakan tombol Batal yang memanggil close(). Jangan andalkan klik backdrop saja Di editor.clincoo.buzz tetap sediakan tombol bertuliskan Batal. Pengguna keyboard tidak mengklik backdrop. Uji di dua lebar Cek preview app.clincoo.buzz di ponsel dan desktop. Klik di luar panel hanya boleh menutup dialog yang memang dirancang light-dismiss."},{"i":"dialog-beda-show-dan-showmodal","c":"dialog","cn":"Dialog HTML","t":"Cara Pilih show atau showModal untuk dialog","d":"Tata cara membedakan show dan showModal di Clincoo supaya jendela non-modal tidak mengunci seluruh halaman.","x":"show() membuka dialog tanpa mode modal: halaman belakang tetap bisa diklik. showModal() mengunci interaksi dan menutup dengan Escape. Salah pilih membuat palet warna di editor terasa macet. Pakai show untuk panel samping Tips singkat, palet, atau catatan yang boleh dibiarkan terbuka saat pengguna mengedit cocok dengan show(). Jangan berharap fokus terkunci. Tutup dengan close() dari tombol yang jelas. Pakai showModal untuk keputusan Konfirmasi hapus, ganti domain, atau buang draf harus showModal(). Di editor.clincoo.buzz jangan campur keduanya pada elemen yang sama tanpa menutup dulu. Cek interaksi latar Di preview app.clincoo.buzz , dialog non-modal harus mengizinkan klik di editor. Dialog modal tidak boleh."},{"i":"dialog-kunci-scroll-latar","c":"dialog","cn":"Dialog HTML","t":"Cara Kunci Scroll Latar saat dialog Modal Terbuka","d":"Tata cara menahan scroll halaman belakang di Clincoo saat dialog modal terbuka, tanpa mengunci scroll di dalam panel.","x":"Di ponsel, gestur gulir sering menggeser halaman di belakang dialog meski showModal sudah dipanggil. Pengguna kehilangan konteks form yang sedang diisi. Tahan overflow pada html Saat showModal, set overflow hidden pada html atau body, dan simpan posisi scroll. Saat close, kembalikan nilai semula lalu scroll ke posisi itu. Jangan set hidden permanen di stylesheet. Biarkan isi dialog menggulir Panel di dalam dialog perlu max-height dan overflow auto. Di editor.clincoo.buzz form panjang harus tetap bisa digulir di dalam jendela, bukan di halaman belakang. Uji di lebar ponsel Buka preview app.clincoo.buzz selebar 390px. Gulir di luar panel tidak boleh menggerakkan latar. Setelah tutup, halaman kembali ke posisi semula."},{"i":"dialog-kembalikan-fokus-ke-pemicu","c":"dialog","cn":"Dialog HTML","t":"Cara Kembalikan Fokus ke Tombol yang Membuka Dialog","d":"Tata cara menyimpan pemicu dialog Clincoo dan mengembalikan fokus ke tombol itu setelah dialog ditutup.","x":"Kalau dialog ditutup lalu fokus hilang ke awal halaman, pengguna keyboard harus mengulang tab. Di editor.clincoo.buzz simpan elemen yang membuka dialog. Simpan pemicu sebelum showModal Pada klik tombol, simpan document.activeElement ke variabel. Baru panggil dialog.showModal(). Jangan membuka dialog dari skrip tanpa tahu tombol mana yang dipanggil. Kembalikan saat close Dengarkan event close. Jika pemicu masih ada di dokumen, panggil focus() padanya. Jangan memindahkan fokus ke body hanya karena dialog sudah tidak tampil. Uji dengan keyboard Di app.clincoo.buzz buka dialog dengan Enter, tutup dengan Escape, lalu pastikan fokus kembali ke tombol yang sama — bukan ke tautan logo."},{"i":"form-hubungkan-label-dengan-for","c":"form","cn":"Form HTML","t":"Cara Hubungkan Label dengan Input lewat for","d":"Tata cara menautkan label dan input di form Clincoo supaya klik teks label ikut fokus ke isian dan pembaca layar menyebut namanya.","x":"Placeholder bukan nama isian. Kalau label hanya teks di sebelah input, klik pada teks itu tidak memindahkan fokus. Di editor.clincoo.buzz hubungkan keduanya dengan for dan id. Samakan for dan id Beri input id yang unik di halaman itu, misalnya id=\"email-kontak\". Label memakai for=\"email-kontak\". Jangan mengulang id yang sama di dua isian. Membungkus input di dalam label juga sah, tetapi for tetap lebih jelas kalau ada elemen di antara teks dan input. Jangan mengandalkan placeholder Placeholder hilang saat pengguna mengetik. Nama isian harus tetap terlihat. Untuk tombol ikon di samping input, tambahkan aria-label, bukan title saja. Cek di preview Di app.clincoo.buzz klik teks label: kursor harus masuk ke input. Tab berurutan harus mengucapkan nama label, bukan “edit text” kosong."},{"i":"form-validasi-bawaan-dan-setcustomvalidity","c":"form","cn":"Form HTML","t":"Cara Pakai Validasi Bawaan dan setCustomValidity","d":"Tata cara memakai required, type, dan setCustomValidity di form Clincoo supaya pesan error muncul tanpa memuat ulang halaman.","x":"Form yang hanya dicek setelah fetch sering mengirim data kosong. Browser sudah punya constraint validation. Di editor.clincoo.buzz pakai atribut dulu, baru pesan kustom. Mulai dari atribut required menahan submit kosong. type=\"email\" menolak teks yang bukan email. minlength menahan kata sandi yang terlalu pendek. Panggil reportValidity() kalau kamu mencegah submit dan ingin gelembung error tampil. Pakai setCustomValidity untuk aturan bisnis Kalau dua isian sandi tidak sama, setCustomValidity(\"Sandi tidak sama\") pada input kedua, lalu reportValidity(). Kalau sudah sama, panggil setCustomValidity(\"\") supaya form tidak terkunci selamanya. Jangan hanya mewarnai border Warna merah tanpa teks tidak terbaca. Di preview app.clincoo.buzz kirim form kosong dan form yang gagal aturan kustom. Pesan harus menyebut isian mana yang salah."},{"i":"form-isi-autocomplete-yang-tepat","c":"form","cn":"Form HTML","t":"Cara Isi Autocomplete yang Tepat pada Form","d":"Tata cara memakai atribut autocomplete di form Clincoo supaya peramban dan pengelola sandi mengisi nama, email, dan alamat dengan benar.","x":"Autocomplete off pada semua input membuat pengguna mengetik ulang data yang sudah tersimpan. Di editor.clincoo.buzz isi token yang sesuai, bukan satu nilai untuk seluruh form. Pakai token standar Nama: autocomplete=\"name\". Email: email. Telepon: tel. Alamat jalan: street-address. Kota: address-level2. Untuk sandi baru pakai new-password, untuk masuk pakai current-password. Jangan menamai input \"password\" lalu memasang autocomplete=\"off\". Satu form, satu tujuan Form masuk dan form daftar sebaiknya terpisah. Mencampur current-password dan new-password di form yang sama membingungkan pengelola sandi. Uji di preview Di app.clincoo.buzz buka form kontak selebar ponsel. Ketuk isian email dan pastikan saran muncul. Jangan menaruh autocomplete=\"off\" hanya karena desain ingin terlihat kosong."},{"i":"form-kelompokkan-radio-dengan-fieldset","c":"form","cn":"Form HTML","t":"Cara Kelompokkan Radio dengan fieldset dan legend","d":"Tata cara membungkus pilihan radio di form Clincoo dengan fieldset dan legend supaya kelompoknya punya nama, bukan hanya opsi yang terpisah.","x":"Tiga radio tanpa kelompok terdengar seperti tiga pertanyaan. Di editor.clincoo.buzz bungkus dengan fieldset dan beri legend. Satu name untuk satu kelompok Semua radio dalam kelompok yang sama memakai name yang sama, misalnya name=\"paket\". Nilai value yang berbeda. Legend menulis pertanyaan: “Pilih paket”. Label tiap radio menulis jawaban: Hemat, Standar, Bisnis. Jangan ganti legend dengan div Judul di dalam div tidak masuk sebagai nama kelompok. fieldset boleh distyle, termasuk border none, selama legend tetap ada. Untuk checkbox yang independen, jangan paksa satu name. Cek keyboard Di app.clincoo.buzz Tab masuk ke kelompok, lalu panah memindahkan pilihan. Pembaca layar harus menyebut legend lalu opsi yang aktif."},{"i":"form-cegah-kirim-ganda","c":"form","cn":"Form HTML","t":"Cara Cegah Form Terkirim Dua Kali","d":"Tata cara menonaktifkan tombol kirim setelah submit di form Clincoo supaya klik ganda tidak membuat dua permintaan.","x":"Tombol kirim yang tetap aktif selama fetch sering membuat dua pesanan atau dua pesan. Di editor.clincoo.buzz kunci tombol setelah submit yang lolos validasi. Kunci setelah cek validity Pada event submit, kalau form.checkValidity() gagal, jangan mengunci tombol. Kalau lolos, preventDefault bila kamu mengirim lewat fetch, lalu setel disabled pada tombol dan ganti teksnya menjadi “Mengirim…”. Simpan teks semula. Kembalikan tombol kalau gagal Di blok catch, hapus disabled dan kembalikan teks. Jangan meninggalkan tombol mati setelah jaringan putus. Untuk permintaan yang membuat data, kirim kunci idempotensi yang sama saat pengguna mengulang, bukan id baru tiap klik. Uji klik ganda Di app.clincoo.buzz klik kirim dua kali cepat. Tab jaringan harus menunjukkan satu permintaan. Setelah gagal, tombol harus bisa diklik lagi."},{"i":"form-textarea-rows-dan-maxlength","c":"form","cn":"Form HTML","t":"Cara Atur Textarea: rows, maxlength, dan label","d":"Tata cara memasang textarea di form Clincoo dengan label, rows, dan maxlength supaya pesan panjang tetap terbaca dan tidak terpotong diam-diam.","x":"Textarea bukan input satu baris yang dipaksa tinggi. Di editor.clincoo.buzz pesan, catatan, atau alamat panjang memakai textarea dengan nama yang jelas. Beri label dan tinggi awal Hubungkan label lewat for dan id. Atribut rows menentukan tinggi awal, misalnya rows=\"4\". Jangan mengunci tinggi dengan CSS yang memotong teks. Pengguna harus bisa melihat beberapa baris sekaligus. Batasi panjang dengan maxlength Kalau backend menolak lebih dari 500 karakter, tulis maxlength=\"500\" pada textarea. Tampilkan sisa karakter di dekat isian jika batasnya ketat. Jangan hanya memotong di server tanpa pesan di halaman. Cek di pratinjau Di app.clincoo.buzz ketik teks yang melewati batas. Peramban harus menahan ketikan, dan label tetap terbacakan oleh pembaca layar. Simpan contoh yang lolos di blog.clincoo.buzz supaya pola yang sama dipakai di form lain."},{"i":"form-select-opsi-kosong-disabled","c":"form","cn":"Form HTML","t":"Cara Buat Opsi Kosong di Select sebagai Placeholder","d":"Tata cara menambah opsi pertama yang disabled dan selected di select Clincoo supaya pengguna memilih nilai sungguhan, bukan label palsu.","x":"Select selalu punya nilai, bahkan sebelum pengguna menyentuhnya. Di editor.clincoo.buzz jangan jadikan opsi pertama sebagai data sungguhan kalau itu hanya petunjuk. Opsi pertama disabled dan selected Tulis option value=\"\" disabled selected. Teksnya boleh “Pilih paket”. Karena value kosong, required pada select gagal saat belum ada pilihan. Jangan memakai option yang bisa dikirim sebagai nama produk. Jangan andalkan option pertama yang valid Kalau opsi pertama adalah paket termurah dan selected, form bisa terkirim tanpa sengaja. Placeholder harus tidak bisa dipilih ulang setelah pengguna memilih yang lain, kecuali Anda memang ingin mengizinkan kosong. Uji keyboard Di app.clincoo.buzz buka select dengan keyboard. Opsi kosong tidak boleh ikut terkirim. Setelah memilih, label tetap terlihat di samping select, bukan hanya di dalam daftar."},{"i":"form-checkbox-value-dan-name","c":"form","cn":"Form HTML","t":"Cara Isi name dan value pada Checkbox","d":"Tata cara memberi name dan value pada checkbox Clincoo supaya hanya yang dicentang yang terkirim, dan setiap kotak punya label sendiri.","x":"Checkbox yang tidak dicentang tidak ikut terkirim. Di editor.clincoo.buzz itu sering mengejutkan kalau Anda mengharapkan nilai “tidak”. Satu name, value yang bermakna Beri name yang sama untuk kelompok, misalnya name=\"topik\", dan value berbeda: \"deploy\" atau \"seo\". Jangan mengandalkan value bawaan \"on\". Label menempel lewat for, bukan teks yang hanya ditulis di sebelahnya. Kalau perlu nilai tidak dicentang Tambahkan input hidden dengan name yang sama dan value=\"0\" sebelum checkbox. Saat dicentang, checkbox menimpa nilai itu di sebagian server. Dokumentasikan perilaku ini supaya tidak dikira bug. Cek payload Di app.clincoo.buzz kirim form dengan satu kotak kosong dan satu tercentang. Panel jaringan hanya boleh memuat value kotak yang dicentang, plus hidden jika Anda memang menambahkannya."},{"i":"form-input-file-accept-tipe","c":"form","cn":"Form HTML","t":"Cara Batasi Tipe File dengan accept","d":"Tata cara memakai accept pada input file di form Clincoo supaya dialog berkas menyaring gambar atau PDF, tanpa menganggap itu validasi keamanan.","x":"Atribut accept hanya membantu dialog berkas. Di editor.clincoo.buzz tetap periksa tipe dan ukuran di server, karena pengguna bisa mengubah berkas yang dipilih. Tulis tipe yang diizinkan Untuk gambar: accept=\"image/png,image/jpeg,image/webp\". Untuk satu PDF: accept=\"application/pdf,.pdf\". Jangan tulis accept=\"*\" kalau Anda hanya ingin gambar. Tambahkan label yang menyebut batas, misalnya “PNG atau JPEG, maks 2 MB”. accept bukan pagar keamanan Peramban bisa mengabaikan saringan. Skrip harus menolak tipe lain sebelum unggah, dan server mengulang pemeriksaan. Jangan menampilkan nama berkas mentah tanpa escape. Uji di pratinjau Di app.clincoo.buzz buka pemilih berkas. Daftar harus condong ke tipe yang diizinkan. Coba pilih berkas lain lewat “semua file” jika peramban mengizinkan, lalu pastikan form menolaknya dengan pesan di dekat input."},{"i":"form-method-post-untuk-data-sensitif","c":"form","cn":"Form HTML","t":"Cara Pilih method POST untuk Data Sensitif","d":"Tata cara memakai method post pada form Clincoo supaya sandi dan data pribadi tidak masuk URL, riwayat, atau log referer.","x":"method=\"get\" menaruh setiap isian di query string. Di editor.clincoo.buzz form login, kontak, dan unggahan memakai method=\"post\". Kapan get masih masuk akal Get cocok untuk pencarian yang boleh dibagikan dan di-bookmark. Jangan menaruh token, sandi, atau email di form get. action harus URL HTTPS di domain yang Anda kendalikan. Post dan enctype Form biasa cukup method=\"post\". Kalau ada input file, tambahkan enctype=\"multipart/form-data\". Tanpa itu berkas tidak ikut terkirim. Tombol kirim harus type=\"submit\" di dalam form. Cek URL setelah kirim Di app.clincoo.buzz kirim form percobaan. Bilah alamat tidak boleh memuat nilai isian. Kalau URL berubah jadi ?email=..., method-nya masih get. Catat pola yang benar di blog.clincoo.buzz sebelum form dipakai pengunjung."},{"i":"form-datalist-saran-tanpa-memaksa-opsi","c":"form","cn":"Form HTML","t":"Cara Pakai datalist untuk Saran tanpa Memaksa Opsi","d":"Tata cara menambahkan datalist pada input Clincoo supaya pengunjung dapat saran, tetapi tetap boleh mengetik nilai di luar daftar.","x":"Select memaksa satu opsi. Kalau pengunjung boleh mengetik sendiri, pakai input plus datalist di editor.clincoo.buzz . Hubungkan list dan id Beri datalist id unik, misalnya id=\"kota-saran\". Input memakai list=\"kota-saran\". Setiap saran adalah option value. Jangan mengulang id datalist di halaman yang sama. Tetap validasi di server Datalist hanya saran di browser. Pengguna tetap bisa mengirim teks bebas. Di form kontak Clincoo, cek panjang dan karakter di sisi yang menerima data, bukan hanya di daftar option. Cek di preview Di app.clincoo.buzz ketik dua huruf: saran harus muncul, dan nilai di luar daftar tetap bisa dikirim. Label tetap terhubung lewat for."},{"i":"form-hidden-bukan-tempat-rahasia","c":"form","cn":"Form HTML","t":"Cara Pakai Input Hidden tanpa Menyimpan Rahasia","d":"Tata cara memakai input hidden di form Clincoo untuk penanda tampilan, bukan untuk kunci API atau token yang tidak boleh terlihat.","x":"Input hidden tetap ada di HTML dan bisa dibaca siapa saja yang membuka sumber halaman. Di editor.clincoo.buzz pakai ia hanya untuk penanda yang aman bocor. Yang boleh disimpan Contoh yang aman: name=\"sumber\" value=\"halaman-harga\" supaya kamu tahu form mana yang dikirim. Jangan taruh kunci pembayaran, sandi, atau token sesi di value hidden. Nama harus unik dan method POST Beri name yang tidak bentrok dengan isian lain. Form yang membawa data ini sebaiknya method post, supaya nilai tidak menempel di URL saat dibagikan. Cek sebelum deploy Di app.clincoo.buzz buka sumber preview dan cari type=\"hidden\". Kalau ada string yang tidak boleh publik, pindahkan ke variabel lingkungan di server, bukan ke halaman."},{"i":"semantic-tombol-bukan-div-klik","c":"semantic","cn":"HTML Semantik","t":"Cara Pakai Button, Bukan Div yang Diklik","d":"Tata cara memakai elemen button untuk aksi di halaman Clincoo supaya keyboard dan pembaca layar tetap bisa memicunya.","x":"Div dengan onclick terlihat seperti tombol, tetapi tidak fokus lewat keyboard dan tidak punya peran tombol. Di editor.clincoo.buzz pakai button untuk aksi yang tidak pindah halaman. Pilih elemen yang sesuai Pakai a href kalau tujuannya pindah URL. Pakai button type=\"button\" kalau tujuannya membuka modal, mengirim filter, atau menyalin teks. Jangan taruh button di dalam a, atau sebaliknya. Beri nama yang terdengar Teks tombol harus menjelaskan aksi: Simpan draf, bukan OK. Kalau tombol hanya ikon, tambahkan aria-label. Jangan mengandalkan warna saja untuk membedakan tombol utama. Uji tanpa mouse Tab sampai tombol fokus, lalu tekan Enter atau Space. Kalau tidak terjadi apa-apa, elemen itu bukan button. Setelah beres, cek lagi di preview lebar ponsel di app.clincoo.buzz karena area sentuh yang terlalu kecil sering terlewat."},{"i":"semantic-landmark-header-main-footer","c":"semantic","cn":"HTML Semantik","t":"Cara Tandai Header, Main, dan Footer","d":"Tata cara membungkus halaman Clincoo dengan landmark header, main, dan footer supaya struktur terbaca tanpa mengandalkan div.","x":"Halaman yang hanya berisi div tidak memberi peta ke pembaca layar. Di editor.clincoo.buzz bungkus tiap halaman dengan header, main, dan footer. Satu main per halaman main membungkus isi unik: judul, teks, dan formulir. Jangan taruh navigasi situs atau kredit di dalam main. Satu halaman cukup satu main. Header dan footer yang jelas header memuat logo dan nav. footer memuat tautan kebijakan dan kontak. Kalau ada dua header, misalnya situs dan kartu artikel, beri aria-label yang berbeda supaya tidak bentrok. Cek di pohon aksesibilitas Buka DevTools, panel Accessibility, lalu lihat landmark. Kamu harus melihat banner atau header, main, dan contentinfo. Kalau tidak ada, elemen itu masih div. Ulangi cek di preview sebelum deploy lewat app.clincoo.buzz ."},{"i":"semantic-daftar-bukan-baris-br","c":"semantic","cn":"HTML Semantik","t":"Cara Buat Daftar, Bukan Baris dengan BR","d":"Tata cara memakai ul, ol, dan li di halaman Clincoo supaya daftar fitur tetap berurutan dan mudah dibaca.","x":"Beberapa baris teks yang dipisah br bukan daftar. Pembaca layar tidak tahu ada berapa butir. Di editor.clincoo.buzz pakai ul atau ol. Pilih ul atau ol ul untuk butir yang setara, misalnya fitur paket. ol untuk langkah yang harus berurutan, misalnya cara deploy. Setiap butir satu li. Jangan menaruh br di dalam li hanya untuk memalsukan butir baru. Jangan reset gaya sampai hilang list-style: none boleh untuk menu, tetapi sisakan jarak dan penanda visual. Menghapus padding kiri tanpa pengganti membuat butir menempel ke tepi dan sulit dipindai. Cek jumlah butir Di pohon elemen, hitung li. Jumlahnya harus sama dengan yang kamu maksud. Tautan di dalam li tetap boleh. Setelah itu buka preview di app.clincoo.buzz dan pastikan daftar tidak overflow di layar sempit."},{"i":"semantic-alt-gambar-bukan-title","c":"semantic","cn":"HTML Semantik","t":"Cara Isi Alt pada Gambar, Bukan Atribut Title","d":"Tata cara menulis alt yang menjelaskan gambar di halaman Clincoo, bukan mengandalkan atribut title yang sering tidak terbaca.","x":"Atribut title pada gambar bukan pengganti alt. Pembaca layar mengumumkan alt; title sering hanya muncul sebagai tooltip di desktop. Di editor.clincoo.buzz isi alt setiap kali img punya makna. Tulis apa yang terlihat Alt yang baik menyebut isi gambar: foto toko di Jalan Malioboro, bukan gambar1.jpg. Jangan mulai dengan kata gambar atau foto kalau konteksnya sudah jelas. Kalau gambar adalah teks dalam bentuk bitmap, salin teks itu ke alt. Kosongkan alt yang murni hiasan Garis dekoratif atau ikon yang sudah punya teks di sampingnya memakai alt kosong: alt=\"\". Jangan menghilangkan atribut alt sama sekali, karena browser akan membacakan nama berkas. Jangan mengulang kalimat yang sama di alt dan di caption. Cek di preview Matikan jaringan sebentar atau pakai gambar yang sengaja gagal dimuat, lalu baca teks pengganti. Setelah itu buka preview di app.clincoo.buzz dan pastikan alt tidak ikut tampil sebagai tooltip yang menyaingi caption."},{"i":"semantic-bungkus-menu-dengan-nav","c":"semantic","cn":"HTML Semantik","t":"Cara Bungkus Menu dengan Elemen Nav","d":"Tata cara memakai nav untuk menu utama dan tautan terkait supaya landmark navigasi terbaca di halaman Clincoo.","x":"Div bernama menu tidak memberi landmark navigasi. Elemen nav memberi tahu browser dan pembaca layar bahwa kelompok tautan itu adalah navigasi. Di editor.clincoo.buzz bungkus menu utama dengan nav, bukan div. Satu nav untuk satu tujuan Menu header, daftar isi, dan tautan footer boleh masing-masing punya nav. Beri aria-label yang membedakan: Menu utama, Daftar isi, Footer. Jangan membungkus setiap tautan satuan dengan nav-nya sendiri. Isi nav dengan daftar Taruh tautan di dalam ul dan li supaya urutan dan jumlah item jelas. Tautan halaman aktif boleh memakai aria-current=\"page\". Jangan memakai button untuk pindah halaman kalau tujuannya URL baru — itu tugas a href. Uji landmark Di pratinjau, tab melewati menu dan pastikan fokus terlihat. Kalau ada dua nav tanpa label, pembaca layar hanya bilang navigasi dua kali. Cek lagi setelah deploy lewat tautan di blog.clincoo.buzz jika menu docs ikut berubah."},{"i":"semantic-figure-dan-figcaption","c":"semantic","cn":"HTML Semantik","t":"Cara Pakai Figure dan Figcaption","d":"Tata cara mengelompokkan gambar, diagram, atau cuplikan kode dengan caption memakai figure di proyek Clincoo.","x":"Caption yang hanya berupa paragraf di bawah img mudah terpisah saat layout berubah. Figure mengikat konten dan keterangannya. Di editor.clincoo.buzz pakai figure untuk gambar, diagram, atau cuplikan yang dirujuk dari teks. Satu figure, satu satuan Masukkan img lalu figcaption. Figcaption boleh di awal atau akhir figure. Tulis keterangan yang menambah makna, bukan mengulang alt. Alt tetap menjelaskan gambar jika gambar gagal dimuat; caption menjelaskan peran gambar di artikel. Jangan untuk semua gambar Ikon tombol dan logo header tidak perlu figure. Figure untuk konten yang bisa dipindah ke lampiran tanpa merusak alur kalimat. Kalau teks berkata lihat gambar di atas, pastikan figcaption punya nomor atau nama yang bisa dirujuk. Cek urutan baca Baca halaman tanpa CSS. Caption harus tetap menempel pada gambar di sumber HTML, bukan hanya secara visual di grid. Simpan lalu buka live preview di app.clincoo.buzz pada lebar ponsel supaya caption tidak terpotong."},{"i":"semantic-tandai-waktu-dengan-time","c":"semantic","cn":"HTML Semantik","t":"Cara Tandai Waktu dengan Elemen Time","d":"Tata cara memakai time dan atribut datetime supaya tanggal di halaman Clincoo bisa dibaca mesin dan manusia.","x":"Teks 3 Okt 2026 enak dibaca, tetapi sulit dipilah skrip. Elemen time menyimpan nilai mesin di datetime dan teks manusia di dalamnya. Di editor.clincoo.buzz tandai tanggal rilis, jadwal, dan stempel artikel dengan time. Isi datetime yang valid Tanggal kalender memakai YYYY-MM-DD, misalnya datetime=\"2026-10-03\". Waktu setempat boleh ditambah jam dan offset: 2026-10-03T23:00+07:00 untuk WIB. Jangan menulis kemarin atau minggu depan di datetime. Teks terlihat tetap manusiawi Isi elemen boleh 3 Oktober 2026 atau 3 Okt. Jangan menampilkan string ISO mentah kalau audiensnya pembaca umum. Satu time untuk satu momen; rentang tanggal memakai dua elemen time. Cek zona waktu Kalau acara punya jam, sebut zona di teks: 23.00 WIB. Tanpa offset, mesin tidak tahu apakah itu UTC. Simpan dan buka preview di app.clincoo.buzz untuk memastikan tanggal tidak terpotong di kartu sempit."},{"i":"semantic-blockquote-dan-cite","c":"semantic","cn":"HTML Semantik","t":"Cara Pakai Blockquote dan Cite","d":"Tata cara menandai kutipan dengan blockquote dan sumber dengan cite supaya tidak tertukar dengan teks biasa di Clincoo.","x":"Paragraf yang hanya diberi tanda kutip atau border kiri tetap teks biasa bagi mesin. Blockquote menandai kutipan dari sumber lain. Di editor.clincoo.buzz pakai blockquote untuk kutipan, bukan untuk catatan penulis. Cite untuk judul karya Nama buku, artikel, atau spesifikasi dibungkus cite. Atribut cite pada blockquote, kalau dipakai, berisi URL sumber, bukan teks terlihat. Tampilkan sumber yang bisa dibaca di footer blockquote, misalnya dalam figcaption atau paragraf kredit. Jangan untuk indent biasa Testimoni yang kamu tulis sendiri bukan kutipan pihak ketiga. Penekanan visual cukup dengan CSS pada aside atau p. Blockquote yang salah membuat pembaca layar mengumumkan kutipan pada teks yang bukan kutipan. Sambungkan ke sumber Kalau mengutip dokumentasi, tautkan judulnya. Simpan lalu cek di preview app.clincoo.buzz bahwa garis kutipan tidak mendorong teks keluar layar ponsel."},{"i":"semantic-details-dan-summary","c":"semantic","cn":"HTML Semantik","t":"Cara Buka-Tutup Konten dengan details dan summary","d":"Tata cara memakai details dan summary di halaman Clincoo supaya bagian panjang bisa dilipat tanpa JavaScript.","x":"Blok FAQ atau catatan lanjutan sering membuat halaman Clincoo terasa panjang. Elemen details plus summary melipat isi itu dan tetap bisa dibuka keyboard, tanpa onclick pada div. Tulis ringkasan yang bisa diklik summary adalah label yang terlihat: “Cara reset password”, bukan “Klik di sini”. Satu details hanya punya satu summary, dan summary harus anak langsung details. Jangan andalkan skrip untuk buka-tutup Browser sudah mengurus atribut open. Di editor.clincoo.buzz cukup tulis details, summary, lalu paragraf jawaban. Tambah open hanya jika bagian itu harus terbuka saat halaman dimuat. Cek di preview ponsel Buka preview di app.clincoo.buzz , ketuk summary, lalu pastikan isi tidak mendorong tombol aksi keluar layar. Tab dari summary harus masuk ke tautan di dalam details."},{"i":"semantic-fieldset-dan-legend","c":"semantic","cn":"HTML Semantik","t":"Cara Kelompokkan Input dengan fieldset dan legend","d":"Tata cara membungkus radio atau checkbox berelasi dengan fieldset dan legend supaya nama kelompok terbaca bantuan layar.","x":"Tiga radio “Paket” tanpa nama kelompok hanya terdengar sebagai opsi terpisah. fieldset mengelompokkan input yang satu pertanyaan, dan legend menamai pertanyaan itu. Satu pertanyaan, satu fieldset Letakkan legend sebagai anak pertama fieldset. Tulis pertanyaan lengkap: “Pilih paket”, lalu tiap opsi punya label sendiri yang menempel ke input. Jangan jadikan legend tombol. Jangan ganti dengan div berbingkai Border CSS tidak memberi nama kelompok. Di editor.clincoo.buzz pakai fieldset untuk pilihan metode bayar, ukuran, atau setuju syarat. disabled pada fieldset menonaktifkan semua kontrol di dalamnya. Uji dengan keyboard Di preview app.clincoo.buzz , pindah antar radio dengan panah, bukan hanya Tab. Legend harus tetap terlihat saat fieldset di-scroll di layar sempit."},{"i":"semantic-strong-bukan-tebal-semu","c":"semantic","cn":"HTML Semantik","t":"Cara Pakai strong dan em, Bukan Tebal Semu","d":"Tata cara menandai kata penting dengan strong atau em di Clincoo, bukan span yang hanya diubah font-weight.","x":"Tebal visual dan penekanan makna bukan hal yang sama. strong menandai bagian penting atau peringatan. em menandai penekanan saat dibaca. span dengan font-weight hanya mengubah tampilan. Pilih elemen sesuai makna Pakai strong untuk “wajib” pada syarat, atau peringatan hapus data. Pakai em untuk kata yang berubah arti jika ditekankan. Jangan membungkus satu paragraf penuh dengan strong. CSS boleh, makna tetap di HTML Di editor.clincoo.buzz kamu boleh menata strong agar tidak terlalu berat, tetapi jangan menggantinya dengan class .bold pada span. b dan i hanya untuk kekhasan tipografi, misalnya istilah asing, bukan untuk peringatan. Baca ulang tanpa gaya Di preview app.clincoo.buzz , pastikan kalimat tetap jelas jika tebal diabaikan. Jika makna hilang tanpa warna atau tebal, pindahkan makna itu ke teks, bukan ke gaya."},{"i":"semantic-caption-dan-th-tabel","c":"semantic","cn":"HTML Semantik","t":"Cara Beri Judul Tabel dengan caption dan th","d":"Tata cara menyusun tabel data di Clincoo dengan caption dan th supaya judul kolom tidak hilang saat dibaca bantuan layar.","x":"Tabel harga yang hanya memakai td terlihat rapi, tetapi judul kolom tidak terhubung ke sel. th menandai header, caption menamai tabel. Nama tabel dulu, header kemudian Letakkan caption sebagai anak pertama table. Tulis apa yang dibandingkan: “Perbandingan paket Clincoo”, bukan “Tabel 1”. Baris header memakai th dengan scope=\"col\". Header baris memakai scope=\"row\". Jangan susun layout dengan table Di editor.clincoo.buzz table hanya untuk data berulang. Kartu fitur dua kolom lebih tepat memakai grid, bukan table tanpa header. Cek scroll di layar sempit Bungkus table dengan elemen yang overflow-x auto, lalu buka preview app.clincoo.buzz selebar ponsel. Caption harus tetap terlihat tanpa memotong header."},{"i":"selamat-datang-di-clinqoo","c":"mulai","cn":"Memulai","t":"Selamat Datang di Clincoo","d":"Pengenalan singkat Clincoo dan peta jalan dari nol sampai situs pertamamu tayang di internet.","x":"Clincoo adalah ruang kerja web untuk membuat, menyunting, dan menerbitkan website dalam satu tempat: editor kode profesional, asisten AI, template siap pakai, terminal terintegrasi, dan tombol deploy. Kamu tidak perlu memasang apa pun di komputer — cukup browser. Artikel ini adalah peta jalan singkat dari nol sampai situs pertamamu tayang di internet. Fitur inti dalam sekilas Fitur Untuk apa Editor kode Menyunting file HTML, CSS, dan JavaScript dengan editor profesional lengkap dengan live preview. Asisten AI Menjelaskan konsep, menulis dan mengubah kode, mengelola file, sampai membantu deploy. Template Membuat situs baru dalam hitungan detik tanpa mulai dari nol. Terminal Menjalankan perintah Linux langsung dari browser untuk pekerjaan teknis. Deploy Menerbitkan situs ke internet dengan HTTPS otomatis, satu klik. Kolaborasi Mengundang anggota tim untuk mengerjakan proyek yang sama. Lima langkah sampai situs pertamamu Buat akun di app.clincoo.buzz dengan Google, GitHub, atau email. Klik proyek baru, lalu pilih template yang paling dekat dengan kebutuhanmu — portofolio, landing page bisnis, atau toko sederhana. Buka file di editor dan ubah isinya. Tekan simpan, dan live preview di samping langsung menampilkan perubahannya. Bicara pada asisten AI kalau macet: minta ia menjelaskan kode yang membingungkan atau menuliskan komponen yang kamu butuhkan. Panduannya ada di artikel Asisten AI Clincoo . Kalau sudah beres, tekan deploy. Dalam beberapa menit situsmu online dengan alamat sendiri — dan kamu bisa memasang domain kustom milikmu. Kuota yang perlu kamu tahu sebagai pengguna baru: paket gratis sudah mencakup 3 proyek aktif, 50 pesan AI per bulan, dan 5 deploy per bulan. Rincian semua paket ada di artikel Paket dan Harga Clincoo . Setelah situs pertama tayang Dari sini kamu bisa mengembangkan ke arah mana pun: belajar konsep web lewat praktek, mengundang rekan lewat fitur kolaborasi tim , atau sekadar memoles desain sampai pas. Kalau menemui kendala, mulai dari Pusat Bantuan — hampir semua masalah umum sudah terjawat di sana."},{"i":"cara-buat-proyek-dari-template","c":"mulai","cn":"Memulai","t":"Cara Membuat Proyek dari Template","d":"Tata cara memilih template di Clincoo, mengganti teks dan gambar, lalu menyimpan proyek pertamamu tanpa mulai dari file kosong.","x":"Template di app.clincoo.buzz adalah situs kecil yang sudah jadi: HTML, CSS, dan JavaScript tersusun, tinggal kamu ganti isinya. Ini cara paling aman untuk proyek pertama karena strukturnya sudah valid. Pilih template yang dekat dengan tujuan Masuk ke akun Clincoo, lalu klik proyek baru. Bandingkan portofolio, landing page, dan halaman bisnis. Pilih yang paling dekat, bukan yang paling ramai animasinya. Beri nama proyek yang pendek dan tanpa spasi, misalnya studio-raya , supaya URL deploy nanti mudah dibaca. Ganti isi, jangan ganti struktur dulu Buka index.html di editor. Ganti judul, paragraf, dan tautan. Biarkan tag dan nama class apa adanya sampai preview terlihat benar. Gambar diganti lewat atribut src atau file di folder gambar, bukan dengan menempel file besar ke tengah HTML. Kalau satu bagian membingungkan, tanyakan asisten AI di editor.clincoo.buzz dengan menyebut nama file. Minta penjelasan dulu, baru minta ubahan kecil. Simpan dan cek sebelum lanjut Tekan simpan, lihat live preview, lalu gulir sampai bawah di lebar desktop dan ponsel. Kalau preview kosong, jangan ganti template — baca konsol dulu. Proyek yang sudah tersimpan tetap ada di daftar proyek meski kamu menutup tab."},{"i":"cara-simpan-dan-cek-live-preview","c":"mulai","cn":"Memulai","t":"Cara Menyimpan File dan Mengecek Live Preview","d":"Tata cara menyimpan HTML, CSS, dan JS di editor Clincoo lalu memastikan preview menampilkan versi terbaru, bukan cache lama.","x":"Di editor.clincoo.buzz , perubahan baru tampil di preview setelah file disimpan. Titik di tab atau tanda belum tersimpan berarti browser masih menjalankan salinan lama. Simpan file yang sedang dibuka Selesai mengedit, tekan simpan atau pintasan Ctrl+S (Command+S di Mac). Tunggu tab kehilangan tanda belum tersimpan sebelum menilai tampilan. Kalau kamu mengubah CSS di file terpisah, simpan file itu juga — menyimpan HTML saja tidak menulis ulang stylesheet. Muat ulang preview dengan benar Kalau warna atau teks tidak berubah, muat ulang panel preview. Untuk CSS yang bandel, hard reload di browser (Ctrl+Shift+R) membersihkan cache preview. Jangan menyalin aturan yang sama ke dua file; browser memakai yang terakhir dimuat dan hasilnya terlihat acak. Cek lebar yang dipakai pengunjung Desktop: sekitar 1280px, pastikan navigasi tidak terpotong. Ponsel: sekitar 390px, pastikan teks tidak meluber ke samping. Kalau hanya satu lebar yang rusak, catat lebarnya sebelum minta bantuan. Biasakan satu perubahan, satu simpan, satu cek. Pola itu membuat regresi mudah diurutkan mundur."},{"i":"cara-deploy-situs-pertama","c":"mulai","cn":"Memulai","t":"Cara Deploy Situs Pertama dari Editor","d":"Tata cara menerbitkan proyek Clincoo ke internet: cek file publik, tekan deploy, lalu buka URL HTTPS yang dihasilkan.","x":"Deploy menyalin file proyek yang sudah disimpan ke hosting ber-HTTPS. Yang belum disimpan tidak ikut. Paket gratis mencakup beberapa deploy per bulan, jadi cek dulu sebelum menekan tombol berulang. Cek sebelum menekan deploy Buka proyek di editor.clincoo.buzz dan simpan semua tab. Pastikan ada index.html di root. Tanpa file itu, pengunjung mendapat halaman kosong atau 404. Lepaskan secret dari file publik. Kunci API tidak boleh tertulis di JavaScript yang diunduh browser. Muat preview sekali lagi dan klik tautan utama. Terbitkan dan buka alamatnya Tekan deploy di editor atau minta asisten AI menerbitkan proyek aktif. Setelah selesai, salin URL yang diberikan dan buka di tab penyamaran. Kalau yang tampil masih versi lama, tunggu sebentar lalu muat ulang — CDN kadang menahan salinan sebelumnya. Domain kustom dipasang setelah URL bawaan sudah benar. Rincian kuota ada di dokumentasi paket, dan akun dikelola di app.clincoo.buzz . Kalau deploy gagal Baca pesan gagal apa adanya, jangan hanya mengulang klik. Perbaiki file yang disebut, simpan, lalu deploy lagi. Kalau kuota habis, tunggu periode berikutnya atau naik paket — mengulang klik tidak menambah jatah."},{"i":"cara-pasang-domain-kustom","c":"mulai","cn":"Memulai","t":"Cara Memasang Domain Kustom","d":"Tata cara mengarahkan domain sendiri ke situs Clincoo yang sudah di-deploy: DNS, tunggu propagasi, lalu cek HTTPS.","x":"Domain kustom dipakai setelah URL bawaan hasil deploy sudah benar. Jangan pasang domain di proyek yang masih halaman kosong. Kelola situs dari editor.clincoo.buzz dan akun dari app.clincoo.buzz . Siapkan deploy yang sudah hidup Buka proyek di editor Clincoo dan pastikan deploy terakhir sukses. Salin URL HTTPS bawaan, buka di tab privat, dan cek judul serta gambar. Baru setelah itu buka pengaturan domain di akun. Isi catatan DNS Di panel registrar, buat catatan yang diminta Clincoo — biasanya CNAME untuk subdomain seperti www, atau A/ALIAS untuk apex. Jangan mencampur dua catatan yang berebut hostname yang sama. Hostname harus persis seperti yang tertulis di layar Clincoo, tanpa spasi. Hapus catatan lama yang mengarah ke hosting sebelumnya pada nama yang sama. Simpan perubahan, lalu kembali ke Clincoo dan tekan cek ulang. Tunggu, lalu uji Propagasi DNS bisa beberapa menit sampai beberapa jam. Kalau cek gagal, tunggu lalu ulangi — menekan berkali-kali tidak mempercepat DNS. Setelah aktif, buka domain di tab privat dan pastikan gembok HTTPS muncul. Kalau deploy belum pernah berhasil, selesaikan dulu artikel deploy situs pertama di docs.clincoo.buzz sebelum menyentuh DNS."},{"i":"cara-cek-tampilan-di-lebar-ponsel","c":"mulai","cn":"Memulai","t":"Cara Mengecek Tampilan di Lebar Ponsel","d":"Tata cara menguji situs Clincoo di lebar layar ponsel lewat preview editor dan perangkat sungguhan sebelum deploy.","x":"Situs yang rapi di laptop sering pecah di ponsel: teks kepanjangan, tombol tertutup, atau gambar melebar. Cek ini di preview editor.clincoo.buzz sebelum menekan deploy. Ubah lebar preview Simpan file HTML dan CSS yang sedang diubah. Sempitkan panel preview, atau pakai mode perangkat di alat pengembang browser pada lebar sekitar 390 piksel. Gulir dari atas sampai bawah. Catat bagian yang terpotong, bukan hanya hero. Yang wajib dilihat Tidak ada scroll horizontal. Kalau ada, cari elemen dengan lebar tetap yang lebih besar dari layar. Tombol dan tautan cukup besar untuk disentuh, dengan jarak antar tautan. Gambar memakai lebar maksimal 100 persen supaya tidak mendorong layout. Menu bisa dibuka tanpa hover, karena ponsel tidak punya hover. Uji di perangkat sungguhan Setelah deploy ke URL bawaan, buka alamat itu di ponsel lewat data seluler, bukan hanya Wi-Fi kantor. Cache lama sering menipu. Kalau masih versi kemarin, muat ulang. Perubahan disimpan di editor.clincoo.buzz , akun dan kuota deploy ada di app.clincoo.buzz ."},{"i":"cara-buat-halaman-kedua","c":"mulai","cn":"Memulai","t":"Cara Membuat Halaman Kedua di Proyek","d":"Tata cara menambah about.html atau kontak, menautkannya dari beranda, dan memastikan jalur relatif tetap utuh di Clincoo.","x":"Beranda saja tidak cukup untuk situs sungguhan. Halaman kedua adalah file HTML baru di proyek yang sama, bukan proyek baru. Kerjakan di editor.clincoo.buzz . Duplikasi yang aman Di pohon file, buat file baru bernama about.html di folder yang sama dengan index.html. Salin kerangka HTML dari index.html: doctype, head, dan tautan CSS. Ganti judul dan isi. Jangan menyalin ulang seluruh stylesheet ke dalam file. Tautan relatif Dari index.html, tautan ke halaman kedua adalah about.html, bukan URL absolut. Dari about.html kembali ke beranda pakai index.html atau ./ . Gambar tetap ../gambar/foto.jpg hanya jika file berada di subfolder. Uji setiap tautan di preview, termasuk yang di footer. Kalau CSS hilang di halaman kedua, jalur href stylesheet salah satu tingkat. Nama file huruf kecil dan tanpa spasi, supaya deploy tidak membedakan besar-kecil. Simpan lalu deploy ulang Simpan kedua file, cek preview, lalu deploy. Halaman baru tidak muncul di internet sebelum deploy berikutnya. Kuota deploy terhitung di app.clincoo.buzz ."},{"i":"cara-commit-git-pertama","c":"mulai","cn":"Memulai","t":"Cara Commit Git Pertama di Proyek","d":"Tata cara menyimpan riwayat perubahan HTML, CSS, dan JS dengan git status, git add, dan git commit di editor Clincoo.","x":"Commit adalah catatan perubahan yang bisa kamu kembalii. Di terminal editor.clincoo.buzz cukup tiga perintah untuk commit pertama yang berguna. Cek apa yang berubah Jalankan git status. File merah berarti belum dilacak atau belum masuk staging. Jangan commit node_modules, file .env, atau cadangan editor. Kalau file itu muncul, tambahkan namanya ke .gitignore lalu ulangi git status. Pilih file yang masuk git add index.html style.css menambah file tertentu. git add . mengambil semua yang tidak diabaikan. Setelah itu git status harus menampilkan file hijau di area staged. Kalau ada yang tidak sengaja masuk, git restore --staged nama-file mengeluarkannya tanpa menghapus isi file. Tulis pesan yang menjelaskan git commit -m \"tambah hero dan tautan halaman tentang\" lebih berguna daripada \"update\". Satu commit untuk satu maksud. Kalau git menolak karena identitas kosong, isi user.name dan user.email hanya di repo ini, lalu commit lagi. Setelah commit, git log --oneline menunjukkan riwayat. Deploy tetap lewat tombol deploy di app.clincoo.buzz , bukan otomatis dari commit."},{"i":"cara-isi-title-dan-meta-deskripsi","c":"mulai","cn":"Memulai","t":"Cara Isi Title dan Meta Deskripsi","d":"Tata cara menulis title unik dan meta description di tiap halaman HTML supaya cuplikan hasil pencarian tidak kosong.","x":"Title dan meta description adalah teks yang sering dipakai mesin pencari sebagai judul dan ringkasan. Di proyek Clincoo keduanya ada di head setiap file HTML, bukan hanya di beranda. Bedakan title dan h1 Tag title yang tampil di tab browser boleh sedikit berbeda dari h1 di halaman. Title sekitar 50–60 karakter, memuat nama halaman lalu merek. Dua halaman dengan title yang sama membingungkan saat tab berjejer. Tulis deskripsi yang mengulang janji halaman Meta name=\"description\" cukup satu kalimat, sekitar 150 karakter, yang menjelaskan apa yang didapat pengunjung. Jangan salin deskripsi beranda ke halaman kontak. Pratinjau di editor.clincoo.buzz tidak menampilkan cuplikan Google, jadi cek lewat View Source bahwa tag ada di head. Satu title per halaman Jangan menaruh dua tag title. Yang kedua diabaikan atau menimpa yang pertama tergantung parser. Setelah deploy dari app.clincoo.buzz , buka URL publik dan pastikan title tab sudah berubah, bukan masih template. Gambar sosial memakai og:title dan og:description terpisah. Kalau belum diisi, salin title dan deskripsi yang sama dulu supaya unggahan tidak kosong."},{"i":"cara-hubungkan-css-dan-javascript","c":"mulai","cn":"Memulai","t":"Cara Hubungkan CSS dan JavaScript","d":"Tata cara menautkan style.css dan script.js dari HTML dengan path relatif yang benar di editor Clincoo.","x":"Halaman polos biasanya berarti CSS atau JS tidak termuat, bukan karena browser menolak file. Path dihitung dari lokasi file HTML yang sedang dibuka di editor.clincoo.buzz . Letakkan link di head Gunakan link rel=\"stylesheet\" href=\"style.css\" jika kedua file satu folder. Jika CSS ada di folder css, href=\"css/style.css\". Href yang diawali garis miring mencari dari akar situs, bukan dari folder proyek di laptopmu. Letakkan script sebelum tutup body script src=\"script.js\" di akhir body menunggu HTML selesai diurai. defer pada script di head juga aman untuk file yang butuh DOM. Jangan memakai onclick inline sambil juga menambah listener di file, atau tombol bisa jalan dua kali. Buktikan file termuat Di panel Network, style.css dan script.js harus status 200. 404 berarti nama atau folder salah. Setelah memperbaiki path, simpan HTML lalu muat ulang preview. Deploy dari app.clincoo.buzz hanya mengirim file yang ada di proyek, jadi file yang tidak diunggah tetap 404 di situs publik. Kalau konsol menulis Unexpected token, file JS yang tertaut mungkin sebenarnya HTML 404. Buka URL skrip di tab baru untuk memastikannya."},{"i":"cara-buka-kembali-proyek-yang-sudah-ada","c":"mulai","cn":"Memulai","t":"Cara Buka Kembali Proyek yang Sudah Ada","d":"Tata cara kembali ke proyek Clincoo yang sudah dibuat, membedakan draf dan situs yang sudah di-deploy.","x":"Proyek tidak hilang saat kamu menutup tab. Masuk lagi ke app.clincoo.buzz dengan akun yang sama — Google, GitHub, atau email — lalu buka daftar proyek. Pilih proyek, bukan template baru Tombol proyek baru membuat salinan dari template. Untuk melanjutkan, klik nama proyek yang sudah ada. Kalau daftar kosong, kamu mungkin masuk dengan akun lain. Simpan dulu sebelum pindah file Di editor.clincoo.buzz , tekan simpan sebelum menutup tab. Live preview menampilkan draf; alamat publik hanya berubah setelah deploy. Jangan menilai hasil dari preview saja kalau kamu sedang mengecek situs yang sudah tayang. Kalau proyek tidak muncul Muat ulang daftar, cek kuota 3 proyek aktif di paket gratis, dan pastikan undangan tim tidak membuatmu membuka ruang kerja orang lain. Proyek yang dihapus tidak kembali dari halaman ini."},{"i":"cara-duplikat-proyek-sebagai-cadangan","c":"mulai","cn":"Memulai","t":"Cara Duplikat Proyek sebagai Cadangan","d":"Tata cara menyalin proyek Clincoo sebelum eksperimen besar supaya versi yang sudah jalan tetap bisa dibuka.","x":"Eksperimen layout atau ganti template bisa merusak halaman yang sudah beres. Duplikat dulu proyek di app.clincoo.buzz supaya ada salinan yang tidak ikut berubah. Salin sebelum mengubah Buka daftar proyek, pilih proyek yang sudah di-deploy, lalu pakai aksi duplikat atau salin. Beri nama yang memuat tanggal, misalnya toko-cadangan-2026-10-03. Jangan menimpa proyek asli. Cek isi salinan Buka salinan di editor.clincoo.buzz . Pastikan index.html, CSS, dan gambar ikut tersalin. Jalankan live preview. Kalau gambar pecah, jalur relatifnya masih mengarah ke folder lama — pindahkan aset ke folder yang sama di salinan. Jangan deploy salinan ke domain utama Domain kustom tetap menempel di proyek asli. Deploy salinan hanya untuk URL pratinjau. Setelah eksperimen beres dan kamu yakin, baru pindahkan perubahan ke proyek utama, atau tukar domain secara sadar. Commit git di proyek asli tetap berguna, tetapi duplikat proyek adalah jaring kedua kalau commit belum sempat dibuat."},{"i":"asisten-ai-clinqoo","c":"dokumentasi","cn":"Dokumentasi","t":"Asisten AI Clincoo","d":"Kemampuan asisten AI di setiap proyek: mengelola file, terminal, pencarian web, deploy, dan batasannya.","x":"Asisten AI ada di setiap proyek Clincoo dan memahami isi workspace-mu. Ia bisa menjawab pertanyaan, menulis dan mengubah kode, mengelola file, sampai menjalankan perintah — kamu tinggal meminta dalam bahasa sehari-hari. Artikel ini menjelaskan apa saja yang bisa ia lakukan, cara memakainya dengan efektif, dan di mana batasnya. Kemampuan asisten Kemampuan Yang bisa kamu minta Kelola file workspace Membuat, membaca, mengubah, mengganti nama, mencari, dan menghapus file atau folder di proyekmu. Terminal Linux Menjalankan perintah di terminal persisten — sesinya bertahan sekitar 10 menit antar-perintah, dan alat yang terpasang tetap ada selama sesi itu. Pencarian web Mencari informasi dan data terbaru dari internet untuk dijadikan dasar jawaban. Membaca halaman web Mengambil isi sebuah URL dan meringkasnya dalam konteks pekerjaanmu. Screenshot situs Mengambil tampilan sebuah URL sebagai gambar — berguna untuk mengecek hasil deploy. Deploy proyek Menerbitkan situs proyek aktif ke internet atas perintahmu. Variabel lingkungan Melihat dan menambahkan env var proyek, serta menguji validitas secret dan API key. Konektor GitHub Membaca dan mengelola repository GitHub-mu lewat integrasi resmi. Cloudflare API Menjalankan operasi Cloudflare yang diizinkan token-mu, misalnya DNS dan Pages. Cara bertanya yang menghasilkan Sebut konteksnya: nama file, gejala yang terlihat, dan hasil yang kamu harapkan. Pertanyaan spesifik menghasilkan jawaban tepat. Satu masalah per obrolan. Percakapan yang bercampur cenderung membuat jawaban melenceng. Kalau saran AI tidak sesuai, tolak dan ajukan ulang dengan konteks lebih rinci — pola lengkapnya dibahas di Masalah Umum dan Solusinya . Transparansi dan batasan Asisten AI adalah asisten, bukan pembuat situs otomatis. Ia tidak bisa mengklik tombol atau mengisi formulir di situs eksternal secara nyata, dan tidak bisa menguji situsmu seolah-olah pengguna sungguhan. Kamu yang meninjau setiap perubahan dan memutuskan mana yang disimpan. AI bisa keliru atau kurang lengkap — terutama soal informasi di luar Clincoo. Untuk pertanyaan tentang Clincoo sendiri, ia menjawab dari basis pengetahuan resmi; untuk hal lain, selalu cek hasilnya sebelum dipakai. Simpan kredensial penting sebagai env var, jangan ditempel begitu saja di percakapan. Kuota percakapan mengikuti paketmu — Starter 50 pesan per bulan. Rinciannya di Paket dan Harga Clincoo ."},{"i":"paket-dan-harga-clinqoo","c":"dokumentasi","cn":"Dokumentasi","t":"Paket dan Harga Clincoo","d":"Struktur paket Starter, Pro, dan Bisnis: kuota deploy, kolaborator, pesan AI, domain, dan cara upgrade.","x":"Clincoo memakai model freemium: paket gratis yang cukup untuk memulai sungguhan, dan paket berbayar saat kebutuhanmu tumbuh. Harga berlaku saat ini selalu tampil di halaman Langganan di akunmu — artikel ini menjelaskan struktur dan batas tiap paket. Starter (gratis) Paket gratis selamanya, dirancang supaya kamu bisa benar-benar membangun dan menerbitkan situs tanpa membayar: 3 proyek aktif, 50 pesan AI per bulan, 5 deploy per bulan, 1 kolaborator per proyek, dan 1 domain kustom dengan HTTPS otomatis. Pro Untuk pekerja rutin: kuota deploy naik menjadi 25x per bulan, 5 kolaborator per proyek, dan kuota lebih besar untuk sisa fiturnya. Bisnis Untuk tim dan kebutuhan produksi: deploy tanpa batas, 20 kolaborator per proyek, dan dukungan penuh untuk operasi yang lebih berat. Batasan Starter Pro Bisnis Deploy per bulan 5x 25x Tanpa batas Kolaborator per proyek 1 5 20 Pesan AI per bulan 50 Lebih besar Lebih besar Proyek aktif 3 Lebih besar Lebih besar Domain kustom 1 Lebih besar Lebih besar Cara upgrade dan berhenti Semua lewat halaman Langganan di akunmu — atau ketuk ikon mahkota di fitur premium untuk melihat pilihan paket. Upgrade aktif begitu pembayaran dikonfirmasi; berhenti berlangganan berlaku di akhir periode tagihan berjalan, tanpa penalti, dan situs yang sudah dideploy tetap online. Fitur premium dan penanda mahkota Beberapa fitur — seperti domain tambahan di luar kuota paket — ditandai ikon mahkota sebagai fitur premium. Penanda ini membantumu melihat sekilas mana yang butuh paket lebih tinggi tanpa harus mencoba-coba. Kalau kamu menemui kendala soal pembayaran atau kuota, cek Masalah Umum dan Solusinya . Pertanyaan ringkas ada di FAQ ."},{"i":"kolaborasi-tim","c":"dokumentasi","cn":"Dokumentasi","t":"Kolaborasi Tim di Clincoo","d":"Cara mengundang anggota tim, kuota kolaborator tiap paket, dan kebiasaan kerja tim yang rapi.","x":"Kolaborasi memungkinkan beberapa orang mengerjakan proyek yang sama: mengundang anggota lewat email dengan pembagian peran yang jelas, sehingga setiap orang tahu apa yang bisa ia kerjakan. Kuota per paket Paket Kolaborator per proyek Starter 1 Pro 5 Bisnis 20 Kuota mengikuti paket akunmu — rincian lengkapnya di Paket dan Harga Clincoo . Mengundang anggota Buka proyek yang ingin kamu bagikan. Masuk ke halaman Kolaborasi dari pengaturan proyek. Masukkan email anggota yang ingin kamu undang. Atur hak aksesnya sesuai kebutuhan tim. Kirim undangan — anggota menerima email berisi tautan untuk bergabung. Setelah bergabung, anggota bisa membuka proyek dari dashboard-nya masing-masing dan bekerja pada file yang sama denganmu. Cara kerja tim yang rapi Sepakati pembagian area file sejak awal — dua orang mengedit file yang sama di waktu sama rawan saling menimpa. Sampaikan perubahan besar lewat diskusi dulu, baru eksekusi. Asisten AI memahami workspace yang sama, jadi tiap anggota bisa memanfaatkannya untuk memahami kode yang ditulis orang lain. Kalau undangan tidak sampai atau anggota tidak bisa membuka proyek, solusinya ada di Masalah Umum dan Solusinya ."},{"i":"cara-pakai-terminal-di-editor","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Memakai Terminal di Editor Clincoo","d":"Tata cara menjalankan perintah Linux di terminal Clincoo: cek folder proyek, lihat file, dan hentikan proses tanpa menghapus pekerjaan.","x":"Terminal di editor.clincoo.buzz menjalankan perintah Linux di sesi proyek. Sesi bertahan beberapa menit antar-perintah, lalu alat yang terpasang di sesi itu hilang kalau sesi berakhir. Perintah yang aman untuk pemula pwd menunjukkan folder tempat kamu berdiri. ls menampilkan file di folder itu. Bandingkan dengan panel file editor. cat index.html mencetak isi file. Berguna kalau preview dan file di panel terasa tidak sama. Jangan menjalankan perintah yang merusak Hindari rm -rf , memindahkan root proyek, atau menginstal paket global yang tidak kamu pahami. Kalau sebuah tutorial menyuruh menempel satu baris panjang, pecah dulu dan tanyakan apa yang diubah. Asisten AI bisa menjalankan perintah, tetapi kamu yang menyetujui. Hentikan proses yang menggantung Kalau server lokal tidak kembali ke prompt, tekan Ctrl+C sekali. Itu mengirim sinyal berhenti, bukan menghapus file. Setelah prompt kembali, jalankan lagi dengan port yang sama hanya jika proses lama sudah mati. Salin keluaran error lengkap — baris terakhir biasanya penyebabnya — sebelum membuka chat bantuan."},{"i":"cara-atur-variabel-lingkungan","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Mengatur Variabel Lingkungan Proyek","d":"Tata cara menyimpan API key sebagai env var di Clincoo, memisahkannya dari kode publik, dan menguji bahwa nilainya terbaca.","x":"Variabel lingkungan menyimpan secret di luar file yang diunduh pengunjung. HTML dan JS statis tetap publik setelah deploy, jadi kunci yang ditempel di situ sama saja dibagikan. Tambahkan variabel Buka pengaturan proyek di editor.clincoo.buzz atau minta asisten AI menambahkan env var. Beri nama huruf besar dengan garis bawah, misalnya MAIL_API_KEY . Jangan pakai spasi. Tempel nilainya sekali. Jangan mengirim nilai yang sama ke chat umum atau ke file README. Pakai nilainya tanpa membocorkannya Kode server atau perintah terminal boleh membaca variabel itu. File index.html yang dikirim ke browser tidak boleh. Kalau layanan harus dipanggil dari halaman statis, lewatkan panggilan lewat endpoint yang memegang secret, bukan lewat kunci di frontend. Uji lalu deploy ulang Minta asisten menguji bahwa secret terisi, tanpa mencetak isinya ke log. Kalau nilai baru tidak terbaca, simpan ulang lalu deploy lagi — proses yang sudah jalan masih memegang nilai lama. Putar kunci di penyedia layanan jika nilai itu pernah tertulis di file publik."},{"i":"api-payment-gateway-qris","c":"dokumentasi","cn":"Dokumentasi","t":"Dokumentasi API Payment Gateway QRIS (ClincooPay)","d":"Referensi resmi ClincooPay: buat transaksi QRIS dari situs deploy-mu via /api/pay, cek status, webhook pembayaran, dan penarikan saldo.","x":"ClincooPay adalah payment gateway bawaan Clincoo: pembeli membayar lewat QRIS, saldo masuk ke dashboard proyekmu, dan kamu bisa mencairkannya kapan pun. Artikel ini adalah dokumentasi resmi API-nya untuk situs yang kamu deploy dari app.clincoo.buzz . Alur besar integrasi Aktifkan Pembayaran di Pengaturan proyekmu, lalu salin pay_key (berawalan clc_pay_ ). Situsmu memanggil POST /api/pay untuk membuat transaksi QRIS. Pembeli diarahkan ke halaman bayar resmi Clincoo, atau kamu menampilkan QR sendiri. Status dicek lewat GET /api/pay?action=status sampai lunas. Saat dibayar, Clincoo mengirim webhook ke URL yang kamu daftarkan. Ringkasan endpoint Endpoint Fungsi Autentikasi POST /api/pay {action:\"create\"} Membuat transaksi QRIS baru pay_key (publik) GET /api/pay?action=status Cek status transaksi pay_key (publik) POST /api/pay {action:\"activate\"} Aktifkan gateway untuk proyek Login Clincoo GET /api/pay?action=config Status, pay_key, dan saldo Login Clincoo POST /api/pay {action:\"withdraw\"} Ajukan penarikan saldo Login Clincoo POST /api/pay {action:\"transactions\"} Log 25 transaksi terakhir Login Clincoo Semua endpoint berada di https://app.clincoo.buzz/api/pay . Pay_key aman dipakai di frontend karena hanya bisa membuat transaksi dan membaca status — kredensial gateway sebenarnya tetap di server Clincoo. Membuat transaksi QRIS Kirim permintaan POST dari situs deploy-mu tanpa perlu login: POST https://app.clincoo.buzz/api/pay Content-Type: application/json { \"action\": \"create\", \"key\": \"clc_pay_....\", \"amount\": 25000, \"description\": \"Paket A\" } Parameter: Field Wajib Keterangan key Ya Pay_key proyekmu, contoh clc_pay_.... amount Ya Integer rupiah, Rp 1.000 sampai Rp 100.000.000 description Tidak Keterangan transaksi, maksimal 100 karakter Contoh respons sukses: { \"success\": true, \"order_id\": \"clincoo....\", \"checkout_url\": \"https://app.clincoo.buzz/pay/?order_id=clincoo....&key=clc_pay_....\", \"amount\": 25000, \"qr_image\": \"https://api.qrserver.com/v1/create-qr-code/?...\", \"qr_string\": \"<payload QRIS>\", \"total_payment\": 25415, \"expires_at\": \"2026-10-03T09:00:00.000Z\", \"is_sandbox\": false } total_payment adalah nominal yang benar-benar dibayar pembeli (nominal + biaya QRIS). Respons 503 gateway_not_ready berarti QRIS server sedang menyiapkan diri — tampilkan pesan itu apa adanya. Cara termudah: pakai halaman bayar resmi Setelah create berhasil, cukup alihkan pembeli ke checkout_url . Halaman bayar resmi Clincoo sudah menampilkan QR, total tagihan, cek status otomatis, dan halaman sukses — kamu tidak perlu membuat halaman bayar sendiri. async function buatBayaran(amount) { const r = await fetch('https://app.clincoo.buzz/api/pay', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'create', key: 'clc_pay_....', amount, description: 'Pembayaran' }) }); const d = await r.json(); if (d.success) window.location.href = d.checkout_url; } Kalau kamu ingin tampilan bayar khusus, alternatifnya: tampilkan qr_image di tag img (atau render qr_string sendiri), lalu polling status seperti di bawah. Cek status transaksi GET https://app.clincoo.buzz/api/pay?action=status&key=clc_pay_....&order_id=clincoo.... { \"success\": true, \"status\": \"paid\", \"amount\": 25000, \"total_payment\": 25415 } Nilai status yang mungkin: Status Arti pending Menunggu pembayaran; QR masih aktif paid Lunas — saldo masuk ke dashboard proyek expired QR kedaluwarsa atau dibatalkan Lakukan polling tiap 3-5 detik sampai status paid, lalu arahkan pembeli ke halaman sukses. Server hanya mengecek ke gateway maksimal satu kali per 4 detik untuk tiap transaksi, jadi polling lebih cepat dari itu tidak memberi hasil baru. Webhook pembayaran Setiap transaksi berubah jadi paid, Clincoo mengirim notifikasi POST ke URL webhook proyekmu (daftarkan di Pengaturan > Webhook): { \"event\": \"payment.paid\", \"order_id\": \"clincoo....\", \"amount\": 25000, \"description\": \"Paket A\", \"status\": \"paid\", \"paid_at\": \"2026-10-03T09:00:00.000Z\" } Selalu cocokkan order_id ke sistemmu sebelum mengaktifkan pesanan. Halaman sukses untuk pembeli tetap perlu dibuat di situsmu. Dashboard pemilik proyek Aksi berikut butuh login Clincoo dan field project_id: Aksi Hasil config Status aktif, pay_key, saldo tersedia, total masuk, total dicairkan summary Ringkasan saldo singkat transactions 25 transaksi terakhir withdraw Penarikan saldo, minimum Rp 10.000, maksimum saldo tersedia withdrawals 25 riwayat penarikan Semua bisa dilakukan dari halaman Pengaturan > Pembayaran di dashboard tanpa menyentuh API. Butuh bantuan? Cek FAQ atau Masalah Umum ."},{"i":"cara-rata-tengah-elemen-dengan-flexbox","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Rata Tengah Elemen dengan Flexbox","d":"Tata cara memusatkan kotak di sumbu utama dan silang memakai Flexbox di editor Clincoo, tanpa margin trik negatif.","x":"Rata tengah yang geser saat lebar berubah biasanya masih memakai margin tetap. Flexbox menghitung sisa ruang sendiri. Ubah di editor.clincoo.buzz lalu cek di live preview. Jadikan induk sebagai flex Pasang display: flex pada elemen pembungkus, bukan pada anak yang ingin dipusatkan. justify-content: center menggeser di sumbu utama. align-items: center menggeser di sumbu silang. Keduanya bersama-sama memusatkan anak di kedua arah. Perhatikan arah sumbu flex-direction: column menukar sumbu. Setelah column, justify-content mengatur vertikal dan align-items mengatur horizontal. Kalau hanya satu sumbu yang pindah, cek properti mana yang kamu ubah. Beri tinggi pada pembungkus align-items tidak terlihat jika tinggi pembungkus sama dengan tinggi anak. Untuk hero, beri min-height, misalnya 60vh. Jangan rata tengah dengan position absolute kecuali elemen memang harus lepas dari alur dokumen. Simpan CSS, muat ulang preview, lalu sempitkan lebar. Jika teks tetap di tengah saat satu kolom, Flexbox sudah benar. Grid lebih pas jika kamu meratakan beberapa sel sekaligus, bukan satu kotak."},{"i":"cara-optimasi-gambar-sebelum-deploy","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Optimasi Gambar Sebelum Deploy","d":"Tata cara mengecilkan gambar, memilih format, dan mengisi width serta alt sebelum situs Clincoo di-deploy.","x":"Gambar penuh dari kamera sering lebih besar daripada seluruh HTML dan CSS. Perkecil sebelum deploy supaya preview dan situs tayang sama-sama cepat. Ubah ukuran ke lebar tampilan Hero selebar 1200 piksel tidak perlu file 4000 piksel. Ekspor ulang mendekati lebar maksimum yang benar-benar ditampilkan. Simpan foto sebagai WebP atau JPEG, ikon datar sebagai SVG, bukan PNG besar. Tulis ukuran dan alt Isi atribut width dan height agar layout tidak meloncat saat gambar masuk. alt menjelaskan isi gambar untuk pembaca layar dan untuk saat file gagal dimuat. Alt kosong hanya untuk gambar murni dekoratif. Jangan muat gambar yang tersembunyi Gambar di bawah lipatan bisa loading=\"lazy\". Gambar hero jangan lazy, karena itu yang dilihat pertama. Cek tab Network: satu gambar di atas 500 KB biasanya masih bisa diperkecil tanpa beda visual yang jelas. Setelah file ringan, simpan di folder aset proyek lalu deploy dari app.clincoo.buzz . Ulangi cek di halaman publik, bukan hanya di preview editor."},{"i":"mengirim-email-dari-situs-deploy","c":"dokumentasi","cn":"Dokumentasi","t":"Mengirim Email dari Situs Deploy di Clincoo","d":"Aktifkan fitur email per proyek, ambil API key di tab Kunci API, lalu kirim pesan dari situs deploy-mu lewat satu request. Kuota 1.000 email per bulan.","x":"Situs yang kamu deploy di Clincoo bisa mengirim email sendiri — dari konfirmasi pesanan, notifikasi form kontak, sampai broadcast ke audiens. Artikel ini menjelaskan langkahnya dari nol sampai request pertama berhasil. Aktifkan fitur email Buka proyek di app.clincoo.buzz, masuk ke menu Email di pengaturan proyek, lalu klik Aktifkan Email . Fitur ini berlaku per proyek, jadi aktifkan pada proyek yang situs deploy-nya memang perlu mengirim pesan. Ambil API key Masuk ke tab Kunci API di halaman yang sama dan salin kunci berformat clc_email_… Simpan kunci sebagai secret di sisi server situs deploy-mu — jangan ditulis mentah di kode yang bisa dibaca publik. Kirim email dengan satu request Dari situs deploy-mu, kirim satu request POST ke https://app.clincoo.buzz/api/email dengan header Content-Type application/json dan body berisi bidang action bernilai send, api_key , to , subject , dan html . Bidang reply_to sifatnya opsional kalau balasan harus masuk ke alamat lain. Uji dulu dengan to diisi alamat emailmu sendiri. Kalau pesan masuk, barulah arahkan request yang sama ke pelanggan atau form kontak di situs deploy-mu. Kuota dan batasan Setiap proyek mendapat kuota 1.000 email per bulan . Cloudflare Email Routing yang dipakai di belakangnya hanya mengirim ke alamat terverifikasi, jadi verifikasi dulu alamat penerima utama sebelum menjadikan jalur ini notifikasi penting. Pantau hasilnya Tab Metrik menampilkan statistik terkirim dan gagal, sedangkan tab Template dan Otomasi membantu menyiapkan isi pesan dan aturan kirim otomatis. Kalau email tidak sampai, periksa API key dan alamat penerima sebelum mencoba kirim ulang."},{"i":"cara-buat-layout-grid-dua-kolom","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Buat Layout Grid Dua Kolom","d":"Tata cara menyusun dua kolom dengan CSS Grid yang jatuh menjadi satu kolom di layar sempit, di editor Clincoo.","x":"Grid cocok untuk kartu sejajar yang harus rata. Di editor.clincoo.buzz bungkus item dengan satu elemen, lalu atur kolom di CSS, bukan dengan tabel. Dua kolom yang sama display: grid dan grid-template-columns: 1fr 1fr membuat dua jalur selebar sama. gap: 1rem memberi jarak tanpa margin yang saling dorong. Anak langsung menjadi sel. Jangan lupa min-width: 0 jika ada teks panjang. Jatuh di ponsel Di media query max-width: 640px, ganti ke grid-template-columns: 1fr. Satu aturan itu lebih aman daripada menyembunyikan kolom. Gambar di dalam sel perlu max-width: 100%. Cek di preview lalu deploy Sempitkan preview dan pastikan tidak ada scroll horizontal. Simpan, lalu terbitkan dari app.clincoo.buzz . Untuk meratakan satu kotak di tengah, tetap pakai Flexbox, bukan Grid."},{"i":"cara-atur-heading-berjenjang","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Atur Heading Berjenjang","d":"Tata cara memakai satu h1 dan heading berurutan di halaman Clincoo supaya judul mudah dipindai manusia dan mesin telusur.","x":"Heading adalah kerangka halaman, bukan cara memperbesar tulisan. Di file HTML proyek editor.clincoo.buzz , pakai satu h1 untuk judul halaman, lalu h2 untuk bagian, h3 untuk anak bagian. Jangan loncat tingkat Setelah h2, lanjut ke h3, bukan langsung h4. Ukuran visual diatur di CSS. Kalau sebuah kalimat hanya perlu tebal, pakai strong atau kelas teks, bukan heading. Samakan h1 dengan title Isi h1 sebaiknya dekat dengan tag title di head, tetapi tidak harus identik. Title untuk tab dan hasil telusur; h1 untuk orang yang sudah membuka halaman. Isi meta description tetap ringkas, satu atau dua kalimat. Cek di pratinjau dan outline Di live preview, scroll dan pastikan hanya ada satu judul utama. Asisten AI Clincoo bisa diminta menandai heading yang loncat tingkat — tempelkan potongan head dan body, bukan seluruh proyek, kalau halamanmu panjang."},{"i":"cara-baca-log-deploy-yang-gagal","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Baca Log Deploy yang Gagal","d":"Tata cara membaca pesan gagal deploy di Clincoo: file hilang, path salah, dan batas ukuran, lalu perbaiki sebelum mencoba lagi.","x":"Deploy gagal biasanya berhenti di satu baris yang menyebut file atau perintah. Baca baris itu di log sebelum menekan deploy lagi di editor.clincoo.buzz . Cari baris pertama yang merah Gulir ke atas sampai pesan error pertama, bukan baris terakhir yang hanya mengulang kegagalan. Catat nama file dan kode status. ENOENT atau 404 berarti file yang dirujuk tidak ada di proyek. Cocokkan dengan isi folder Buka pohon file. Nama di log harus sama persis, termasuk huruf besar. index.HTML tidak sama dengan index.html. Path yang diawali garis miring mencari dari akar situs, path tanpa garis miring mencari relatif terhadap halaman. Ukuran dan env Kalau log menyebut kuota atau file terlalu besar, kecilkan gambar lalu deploy ulang. Kalau log menyebut variabel kosong, isi env di pengaturan proyek, bukan di file yang ikut ter-commit. Setelah perbaikan, deploy sekali lagi dan simpan URL yang sukses di app.clincoo.buzz ."},{"i":"cara-tarik-saldo-dari-clinqoo","c":"dokumentasi","cn":"Dokumentasi","t":"Cara Tarik Saldo Penghasilan dari Clincoo","d":"Panduan resmi pencairan saldo ClincooPay: tambah tujuan e-wallet, verifikasi OTP email, potongan biaya layanan, dan cara membaca riwayat penarikan.","x":"Penghasilan dari pembayaran QRIS ClincooPay masuk ke saldo proyekmu di app.clincoo.buzz dan bisa dicairkan kapan pun dari halaman yang sama. Panduan ini menjelaskan alur resmi penarikan saldo: menambah tujuan, verifikasi OTP, sampai membaca riwayat penarikan. Sebelum menarik Fitur Pembayaran sudah aktif di proyekmu dan saldo tersedia cukup — penarikan minimal Rp 10.000 , termasuk biaya layanan. Siapkan akses ke email pemilik proyek: kode verifikasi penarikan dikirim ke sana. Tambahkan tujuan penarikan Di Pengaturan proyek, buka Pembayaran lalu pilih tujuan penarikan. Pilih jenis e-wallet dan isi nomor HP yang benar-benar milikmu — nama pemilik akun e-wallet harus sesuai pemilik proyek. Untuk keamanan, Clincoo dapat meminta verifikasi ulang lewat OTP email saat tujuan baru terindikasi mencurigakan, misalnya sering berganti atau ditambah dari jaringan baru. Ajukan penarikan dengan OTP Masukkan nominal yang ingin dicairkan. Clincoo mengirim kode OTP 6 digit ke email pemilik proyek. Kode berlaku 10 menit dan maksimal 5 kali percobaan. Masukkan kodenya untuk mengajukan penarikan. Nominal plus biaya layanan langsung dikunci dari saldo tersedia. Biaya layanan dipotong otomatis dan angka finalnya selalu tertera sebelum kamu mengonfirmasi. Kalau saldo kurang, kurangi nominalnya — jangan mengulang klik pada tombol yang sama. Baca riwayat penarikan Setiap penarikan tercatat dengan statusnya: Pending saat sedang diproses, Selesai saat dananya terkirim, atau Ditolak . Penarikan yang ditolak mengembalikan nominal dan biaya ke saldo proyek. Setiap perubahan status juga dikirim ke email pemilik proyek. Kalau penarikan lama tetap pending, mulai dari Masalah Umum sebelum mengajukan yang baru. Rincian teknis API penarikan ada di dokumentasi ClincooPay ."},{"i":"faq-clinqoo","c":"bantuan","cn":"Pusat Bantuan","t":"Pertanyaan yang Sering Diajukan (FAQ)","d":"Jawaban cepat untuk pertanyaan paling umum seputar akun, paket, AI, kolaborasi, dan deploy di Clincoo.","x":"Kumpulan jawaban untuk pertanyaan yang paling sering masuk. Kalau jawabanmu tidak ada di sini, lihat artikel Masalah Umum dan Cara Mengatasinya di kategori yang sama. Apakah Clincoo gratis? Ya. Paket Starter gratis selamanya dan sudah termasuk editor, chat AI (50 pesan per bulan), 3 proyek aktif, dan deploy web 5x per bulan. Paket berbayar hanya dibutuhkan saat kebutuhanmu melebihi batas itu. Perbandingan lengkap ada di artikel Paket dan Harga . Cara membuat akun? Buka app.clincoo.buzz dan masuk lewat Google, GitHub, atau daftar dengan email. Panduan lengkapnya di artikel Selamat Datang di Clincoo . Apakah saya harus bisa coding? Tidak harus. Template siap pakai memungkinkan situs jadi tanpa menulis kode, dan asisten AI bisa membantu menulis atau mengubah kode untukmu. Meski begitu, sedikit pemahaman HTML/CSS akan membuat hasilnya jauh lebih baik — dan blog ini ada untuk mengajarkan itu pelan-pelan. Apakah AI bisa membuat situs otomatis? AI adalah asisten, bukan pembuat situs otomatis. Ia membantu menjelaskan, menulis kode, dan menyusun konten, tetapi tidak bisa mengklik tombol atau menguji situsmu secara nyata. Kamu yang meninjau dan memutuskan setiap perubahan. Detailnya di artikel Asisten AI Clincoo . Berapa lama situs saya aktif setelah deploy? Situs yang sudah dideploy tetap online. Kamu bisa deploy ulang kapan saja untuk menerbitkan versi terbaru, dan kuota deploy mengikuti paketmu — Starter 5x per bulan, Pro 25x, Bisnis tanpa batas. Bisakah pakai domain sendiri? Bisa. Fitur domain kustom tersedia di pengaturan proyek dengan HTTPS otomatis: kamu tinggal memasukkan domain dan mengatur record DNS sesuai petunjuk. Paket gratis sudah termasuk satu domain; tambahan domain adalah fitur premium yang ditandai ikon mahkota. Bagaimana cara upgrade atau berhenti berlangganan? Semua lewat halaman Langganan di akunmu. Upgrade aktif begitu pembayaran dikonfirmasi; berhenti berlangganan (turun ke gratis) berlaku di akhir periode tagihan berjalan, tanpa penalti. Apakah data saya aman? File proyek dan data akun disimpan di infrastruktur Cloudflare. Cara kami mengumpulkan dan memakai data dijelaskan terbuka di Kebijakan Privasi Clincoo . Kamu juga bisa menghapus akun beserta seluruh datanya kapan saja dari zona bahaya di pengaturan. Bisa kerja sama dengan orang lain? Bisa. Fitur kolaborasi memungkinkan kamu mengundang anggota lewat email dengan pembagian peran yang jelas. Batasnya per paket: Starter 1 kolaborator per proyek, Pro 5, Bisnis 20. Panduannya di artikel Kolaborasi Tim ."},{"i":"masalah-umum-dan-solusinya","c":"bantuan","cn":"Pusat Bantuan","t":"Masalah Umum dan Cara Mengatasinya","d":"Tabel ringkas gejala → penyebab → solusi, plus penjelasan detail untuk masalah yang paling sering dialami.","x":"Sembilan dari sepuluh masalah di Clincoo punya penyebab yang sama dan perbaikan yang cepat. Ringkasannya begini — detail tiap kasus menyusul di bawah. Gejala Kemungkinan penyebab Perbaikan cepat Tombol login tidak merespons Popup browser terblokir Izinkan popup untuk app.clincoo.buzz Live preview tidak berubah File belum disimpan / cache Simpan lalu muat ulang preview Deploy gagal Kuota habis atau file utama salah nama Cek kuota & pastikan index.html ada Situs live tampil versi lama Cache jaringan (CDN) Tunggu beberapa menit atau buka mode penyamaran AI menjawab melenceng Pertanyaan terlalu umum Sebutkan file, gejala, dan hasil yang diharapkan Proyek hilang dari dashboard Terhapus (masih di sampah) Pulihkan dari sampah sebelum dihapus permanen Gambar tidak tampil di situs Jalur file salah / nama beda kapital Pakai jalur relatif dan cocokkan nama persis Gagal login atau tombol OAuth tidak merespons Login Google/GitHub Clincoo terbuka di jendela baru. Kalau popup terblokir, tombol terasa mati padahal tidak. Izinkan popup untuk app.clincoo.buzz lalu coba lagi. Untuk login email, gunakan opsi reset sandi di halaman masuk kalau sandi terlupa. Live preview tidak menampilkan perubahan Perubahan tampil setelah file disimpan dan preview dimuat ulang. Kalau masih versi lama, kemungkinan besar cache browser: muat ulang preview dengan tombol refresh, atau bersihkan cache situs untuk app.clincoo.buzz. Deploy gagal atau error Cek kuota deploy di paketmu (Starter 5x, Pro 25x per bulan). Pastikan file utama situs bernama index.html — bukan Index.html atau home.html. Pastikan tidak ada file yang terlalu besar untuk diunggah. Tunggu sebentar lalu coba deploy ulang; gangguan sesaat jarang berlangsung lama. Situs yang dideploy tampil versi lama Jaringan pengiriman (CDN) kadang menyimpan versi lama beberapa menit. Tunggu sebentar lalu muat ulang, atau buka alamat situs dalam mode penyamaran. Kalau versi lama bertahan lebih dari satu jam, deploy ulang dari Clincoo. AI menjawab melenceng atau mengubah file yang tidak diminta Tolak saran itu, lalu ajukan ulang dengan konteks lebih spesifik: sebutkan nama file dan hasil yang diharapkan. Satu masalah per obrolan menghasilkan jawaban jauh lebih akurat. Pola lengkapnya di artikel Asisten AI Clincoo . Proyek hilang dari dashboard Proyek yang dihapus bisa dipulihkan dari sampah (trash) selama belum dihapus permanen. Setelah dihapus permanen, pemulihan tidak tersedia — karena itu selalu tinjau dua kali sebelum konfirmasi hapus. Masih bermasalah? Laporkan lewat menu bantuan di aplikasi dengan menyertakan: apa yang kamu lakukan, apa yang terjadi, pesan error jika ada, dan jenis perangkat. Semakin lengkap laporanmu, semakin cepat masalah bisa ditelusuri."},{"i":"cara-baca-error-console-di-preview","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Membaca Error Console di Preview","d":"Tata cara membuka konsol browser, membedakan error dan warning, lalu menelusuri file yang bermasalah di preview Clincoo.","x":"Kalau preview di editor.clincoo.buzz tampil kosong atau tombol tidak bereaksi, biasanya JavaScript berhenti di error pertama. Konsol browser adalah tempat error itu ditulis, bukan di tampilan halaman. Buka konsol Di Chrome atau Edge, klik kanan area preview lalu pilih Inspect. Buka tab Console. Jika preview ada di iframe, pilih frame preview di pemilih konteks konsol supaya log situsmu yang muncul, bukan log editor. Bedakan jenis pesan Error berwarna merah menghentikan skrip di baris itu. Warning kuning biasanya tidak menghentikan halaman. Info biasa hanya catatan. Perbaiki error merah dulu, dari yang paling atas, karena error berikutnya sering hanya ikutannya. Baca lokasi file Klik tautan file:baris di kanan pesan, misalnya app.js:42 . Itu baris yang browser gagal jalankan. Pesan is not defined berarti nama variabel atau fungsi belum ada. Unexpected token biasanya tanda kutip, kurung, atau koma yang belum ditutup. Salin pesan lengkap, nama file, dan barisnya sebelum minta bantuan di chat AI Clincoo. Jangan hanya menulis \"error\". Setelah perbaikan, simpan file lalu muat ulang preview supaya konsol bersih dari error lama."},{"i":"cara-minta-bantuan-ai-saat-stuck","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Minta Bantuan AI Saat Stuck","d":"Pola permintaan yang membuat asisten AI Clincoo menjawab tepat: satu masalah, file terkait, gejala, dan hasil yang diharapkan.","x":"Asisten AI di Clincoo membantu menjelaskan dan menulis cuplikan, tetapi ia tidak melihat layarmu. Kualitas jawaban mengikuti konteks yang kamu kirim lewat chat di app.clincoo.buzz . Satu masalah per obrolan Jangan gabungkan perbaiki layout, ganti warna, dan sambungkan form dalam satu pesan. Sebutkan satu gejala. Contoh: tombol kirim di index.html tidak memanggil fungsi kirimForm. Sertakan bukti Tempel pesan error lengkap, nama file, dan cuplikan pendek di sekitar baris yang gagal. Sebutkan browser dan lebar layar kalau masalahnya tampilan. Tuliskan hasil yang kamu inginkan dalam satu kalimat. Batasi perubahan Minta daftar perubahan, bukan rewrite seluruh stylesheet. Tolak saran yang mengganti nama merek, menghapus file lain, atau menulis ulang bagian yang masih benar. Uji saran di preview dulu, baru simpan. Kalau jawaban melenceng, ulangi dengan potongan kode yang lebih kecil. Simpan prompt yang berhasil di catatan proyek supaya lain kali kamu tidak mulai dari nol."},{"i":"cara-rapikan-struktur-folder-proyek","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Merapikan Struktur Folder Proyek","d":"Tata cara menata index.html, css, js, dan gambar supaya jalur relatif tidak patah saat preview maupun deploy Clincoo.","x":"Deploy Clincoo memakai file di proyekmu apa adanya. Kalau nama dan folder tidak konsisten, gambar hilang hanya di situs live padahal preview terasa benar. Satu pintu masuk File utama harus bernama index.html di akar proyek, huruf kecil semua. Home.html atau Index.HTML tidak dibaca sebagai halaman depan. Folder yang cukup Pola yang aman untuk situs kecil: css/style.css , js/app.js , dan img/ untuk gambar. Dari index.html, tautan ditulis relatif: css/style.css , bukan jalur komputer lokal seperti C:/Users/. Huruf besar kecil Nama file di server peka huruf. Foto.JPG dan foto.jpg adalah file berbeda. Samakan ejaan di tag img dan nama unggahan. Sebelum deploy dari editor, buka tiap tautan di preview. Kalau satu gambar pecah, perbaiki jalurnya dulu. Proyek rapi juga memudahkan AI menunjuk file yang tepat saat kamu minta bantuan."},{"i":"cara-melanjutkan-pembayaran-tertunda","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Melanjutkan Pembayaran yang Belum Selesai","d":"Langkah cepat melanjutkan pesanan QRIS yang tertunda: buka halaman pembayaran, buat ulang kode kedaluwarsa, dan pastikan paket aktif otomatis setelah bayar.","x":"Saat kamu membeli paket atau membayar lewat QRIS, pesanan berstatus menunggu pembayaran sampai dana kami terima. Kode QRIS kedaluwarsa beberapa menit setelah dibuat — kalau belum sempat bayar, pesanan tertunda dan paket belum aktif. Kabar baiknya, melanjutkannya mudah. Buka halaman pembayaran Cek email pengingat dari Clincoo dan klik tombol Lanjutkan Pembayaran , atau buka notifikasi di aplikasi lalu ketuk pesan pengingat. Kamu juga bisa masuk ke halaman Langganan di app.clincoo.buzz dan pilih paket yang sama. Buat ulang pesanan Kode QRIS yang lama sudah kedaluwarsa, jadi cukup ulangi konfirmasi pembayaran di halaman checkout — sistem otomatis membuat kode QRIS baru. Scan kode itu dengan aplikasi pembayaran atau mobile banking favoritmu, lalu selesaikan pembayaran sebelum waktunya habis. Sudah bayar? Tidak perlu apa-apa Kalau kamu sebenarnya sudah membayar, abaikan email pengingatnya. Paket atau saldo aktif otomatis begitu pembayaran terkonfirmasi — biasanya dalam hitungan menit. Kamu bisa memastikan statusnya di halaman Langganan. Masih bermasalah setelah membayar dan paket belum aktif lebih dari satu jam? Hubungi kami lewat halaman Pusat Bantuan dengan menyertakan nomor pesanan dari email."},{"i":"cara-debug-css-selector-tidak-kena","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Debug CSS yang Selektorya Tidak Kena","d":"Tata cara memakai panel Styles di preview Clincoo untuk mencari aturan yang menimpa, salah eja, atau kalah spesifisitas.","x":"Kalau class sudah ditulis tapi tampilan tidak berubah di editor.clincoo.buzz , selektor biasanya kalah, salah ketik, atau file CSS belum terhubung. Cek apakah file CSS termuat Di tab Network, saring CSS. Status 404 berarti path di tag link salah. Path relatif dihitung dari file HTML, bukan dari folder tempat kamu mengira file itu berada. Simpan kedua file lalu muat ulang preview. Lihat aturan yang menang Klik kanan elemen, pilih Inspect, lalu buka tab Styles. Aturan yang dicoret berarti ditimpa. Aturan di bawah yang lebih spesifik, atau yang memakai !important, biasanya pemenangnya. Samakan spesifisitas, jangan langsung menambah !important. Cocokkan nama class Bandingkan huruf class di HTML dan CSS, termasuk tanda hubung. .tombol-utama tidak sama dengan .tombol_utama. Pseudo-class seperti :hover hanya aktif saat kursor di atas elemen, jadi uji dengan mengaktifkan state :hover di panel Styles. Setelah ketemu aturan pemenang, salin selektor dan nama file ke chat AI Clincoo. Sertakan potongan HTML dan CSS yang bersangkutan, bukan hanya kalimat \"CSS tidak jalan\"."},{"i":"cara-perbaiki-form-yang-tidak-terkirim","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Perbaiki Form yang Tidak Terkirim","d":"Tata cara menelusuri tombol submit, atribut name, dan event preventDefault saat form di preview Clincoo tidak mengirim data.","x":"Form yang diam setelah diklik hampir selalu gagal di HTML atau di handler JavaScript, bukan di server dulu. Uji di preview editor.clincoo.buzz sebelum menyalahkan endpoint. Pastikan tombol ada di dalam form Tombol type=\"submit\" harus berada di dalam tag form, atau punya atribut form yang menunjuk ke id form. type=\"button\" tidak mengirim form. Enter di input teks juga hanya mengirim jika ada satu tombol submit. Beri name pada input Hanya kontrol yang punya atribut name yang ikut dalam FormData dan query string. id saja tidak cukup. Cek required dan type=\"email\": browser menahan kiriman jika nilai tidak lolos, biasanya dengan gelembung validasi di dekat input. Cek preventDefault Jika skrip memanggil event.preventDefault() lalu lupa fetch, halaman tidak pindah dan data tidak pergi ke mana pun. Di konsol, pasang log di awal handler. Kalau log tidak muncul, selektor form salah atau skrip berhenti di error sebelumnya. Untuk formulir akun Clincoo sendiri, lanjutkan dari app.clincoo.buzz . Untuk form di situs yang kamu buat, perbaiki HTML dulu, baru hubungkan action atau fetch."},{"i":"cara-baca-referenceerror-is-not-defined","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Baca ReferenceError is not defined","d":"Tata cara menelusuri baris, nama variabel, dan urutan skrip saat konsol preview Clincoo menulis ReferenceError.","x":"ReferenceError muncul saat JavaScript memakai nama yang belum dideklarasikan. Di preview editor.clincoo.buzz buka konsol, catat nama yang merah, lalu cari nama itu di file yang disebut. Baca nama dan barisnya Pesan seperti menuToggle is not defined berarti skrip memanggil menuToggle, tetapi tidak ada var, let, const, atau fungsi dengan nama itu di lingkup yang sama. Angka baris di konsol mengarah ke pemanggilan, bukan selalu ke tempat yang seharusnya mendeklarasikan nama. Cek urutan dan ejaan Skrip di head yang memakai defer jalan setelah HTML diurai. Skrip biasa di head jalan sebelum tombol ada, tetapi nama fungsi tetap harus sudah dideklarasikan saat dipanggil. Salah ketik satu huruf, misalnya MenuToggle versus menuToggle, dihitung sebagai nama lain. Jangan sembunyikan error Mengosongkan catch tanpa log membuat halaman diam dan error hilang. Tampilkan error di konsol, perbaiki deklarasi, lalu simpan dan muat ulang preview. Kalau masih macet, kirim pesan error utuh ke asisten di app.clincoo.buzz ."},{"i":"cara-perbaiki-gambar-yang-pecah","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Perbaiki Gambar yang Pecah di Preview","d":"Tata cara mencocokkan src, huruf besar, dan folder gambar saat ikon pecah muncul di live preview Clincoo.","x":"Ikon gambar pecah hampir selalu salah jalur, bukan file yang rusak. Di editor.clincoo.buzz klik gambar, lihat src di panel elemen, lalu bandingkan dengan nama file di pohon proyek. Samakan jalur relatif Dari index.html di akar, src=\"images/hero.jpg\" mencari folder images di sebelah index.html. Dari halaman di folder tentang, jalur yang sama mencari tentang/images/hero.jpg. Naik satu folder dengan ../images/hero.jpg. Huruf besar dan ekstensi Hero.JPG dan hero.jpg adalah file berbeda di banyak server. Ekstensi .jpeg tidak sama dengan .jpg. Spasi di nama file lebih aman diganti tanda hubung, lalu src diperbarui. Cek file benar-benar ada Kalau file belum diunggah, unggah dulu baru simpan HTML. Setelah deploy dari app.clincoo.buzz , buka URL gambar langsung. Status 404 berarti jalur di situs tayang masih salah."},{"i":"cara-hilangkan-scroll-horizontal","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Hilangkan Scroll Horizontal di Ponsel","d":"Tata cara menemukan elemen yang lebih lebar dari layar saat preview Clincoo bisa digeser ke samping.","x":"Scroll horizontal di ponsel biasanya datang dari satu elemen yang melebihi lebar viewport. Di preview editor.clincoo.buzz sempitkan panel sampai lebar ponsel, lalu gulir ke samping untuk memastikan gejalanya nyata. Cari yang melebar Di konsol tempel document.querySelectorAll('*') lalu bandingkan scrollWidth dengan clientWidth. Elemen yang scrollWidth-nya lebih besar adalah tersangka. Sering kali itu gambar tanpa max-width, tabel, atau teks panjang tanpa spasi. Batasi lebar img, video, dan iframe perlu max-width: 100% dan height: auto. Kontainer grid atau flex yang tidak boleh menyusut perlu min-width: 0 pada anak. Padding besar ditambah width: 100% tanpa border-box juga mendorong halaman keluar. Uji lagi sebelum deploy Setelah perbaikan, scroll kiri-kanan harus hilang di lebar 360 piksel. Baru deploy dari app.clincoo.buzz . Jangan sembunyikan gejala dengan overflow-x: hidden di body sebelum penyebabnya ketemu."},{"i":"cara-hubungkan-label-ke-input","c":"bantuan","cn":"Pusat Bantuan","t":"Cara Hubungkan Label ke Input Form","d":"Tata cara memakai for dan id supaya label bisa diklik dan pembaca layar mengumumkan nama bidang di form Clincoo.","x":"Placeholder bukan label. Di form yang kamu susun di editor.clincoo.buzz , setiap input perlu nama yang tetap terlihat. Pasangkan for dan id label for=\"email\" harus menunjuk ke input id=\"email\". Klik teks label lalu fokus pindah ke bidang. id wajib unik di halaman. Jangan memakai id yang sama untuk dua input. Bungkus atau hubungkan Membungkus input di dalam label juga menghubungkan keduanya tanpa for. Pilih satu cara dan konsisten. Untuk kotak centang, label di samping membuat area klik lebih besar. Jangan andalkan placeholder Placeholder hilang saat pengguna mengetik. Tambahkan label, lalu aria-describedby hanya untuk petunjuk tambahan. Uji dengan Tab. Setelah beres, deploy dari app.clincoo.buzz ."},{"i":"syarat-dan-ketentuan","c":"legal","cn":"Legal","t":"Syarat dan Ketentuan Penggunaan Clincoo","d":"Aturan penggunaan layanan Clincoo: akun, konten pengguna, pembayaran langganan, batasan layanan, dan penangguhan akun.","x":"Terakhir diperbarui: 3 Oktober 2026. Dengan membuat akun dan memakai Clincoo (app.clincoo.buzz beserta seluruh subdomainnya), kamu menyetujui syarat dan ketentuan berikut. Bacalah dengan saksama — dokumen ini menjelaskan hak dan kewajibanmu sebagai pengguna. 1. Tentang layanan Clincoo menyediakan ruang kerja daring untuk membuat, menyunting, dan menerbitkan website, termasuk editor kode, asisten AI, template, dan layanan deploy. Kami berupaya menjaga layanan tetap tersedia, namun tidak menjamin layanan bebas gangguan tanpa henti sama sekali. Fitur dapat berubah seiring perkembangan produk. 2. Akun pengguna Kamu wajib memberikan informasi akun yang benar dan menjaga kerahasiaan kredensial masukmu. Akun bersifat pribadi; tanggung jawab atas aktivitas yang terjadi lewat akunmu ada padamu. Kamu dilarang membuat akun untuk tujuan penipuan atau penyalahgunaan layanan. 3. Penggunaan yang diizinkan dan dilarang Diizinkan Dilarang Membangun situs pribadi, bisnis, dan proyek sah Mendistribusikan malware atau kode berbahaya Menerbitkan konten milikmu sendiri Melanggar hak kekayaan intelektual pihak lain Berkolaborasi dalam batas paket Mengirimkan spam dari situs yang diterbitkan Memakai AI untuk membantu pekerjaan sah Menyimpan atau menyebarkan konten ilegal Mengotomatiskan tugas yang wajar Mengganggu infrastruktur atau menyalahgunakan kuota secara otomatis 4. Konten pengguna Semua konten yang kamu unggah dan buat di Clincoo (kode, teks, gambar, situs yang diterbitkan) tetap milikmu. Kami hanya memprosesnya untuk menjalankan layanan: menyimpan, merender, menerbitkan, dan mem-backup. Kamu bertanggung jawab memastikan kontenmu tidak melanggar hukum atau hak pihak lain. 5. Asisten AI Fitur AI disediakan sebagai alat bantu. Keluaran AI dapat tidak akurat atau tidak lengkap; kamu wajib meninjaunya sebelum diterapkan. Clincoo tidak bertanggung jawab atas kerugian akibat penggunaan keluaran AI tanpa peninjauan. AI tidak dimaksudkan untuk menghasilkan konten yang melanggar bagian 3. 6. Paket berbayar dan pembayaran Fitur berbayar (paket Pro dan Bisnis) berlaku selama langganan aktif dan tagihan dibayar lunas. Upgrade dan downgrade berlaku sesuai ketentuan di halaman langganan. Kecuali diwajibkan hukum, pembayaran yang telah dilakukan untuk periode berjalan tidak dikembalikan saat kamu berhenti di tengah periode; langganan akan berakhir di akhir masa tagihan. 7. Batas layanan Paket Proyek aktif Chat AI / bln Deploy web / bln Kolaborator Starter 3 50 pesan 5x 1 / proyek Pro 10 500 pesan (maks 50/hari) 25x 5 / proyek Bisnis 50 500 pesan (maks 50/hari) Tanpa batas 20 / proyek Batas ini dapat berubah dengan pemberitahuan di aplikasi atau blog resmi. Pelanggaran batas secara sistematis dapat menyebabkan pembatasan sementara akun. 8. Penangguhan dan penghentian Kami dapat menangguhkan atau menghentikan akun yang melanggar ketentuan ini, menyalahgunakan layanan, atau membahayakan pengguna lain. Sedapat mungkin, pemberitahuan dikirim lebih dulu kecuali situasi mendesak. Kamu dapat menghentikan akunmu kapan saja lewat pengaturan, dan penghapusan akun menghapus data sesuai kebijakan privasi. 9. Batasan tanggung jawab Layanan disediakan \"sebagaimana adanya\". Sepanjang diizinkan hukum, Clincoo tidak bertanggung jawab atas kerugian tidak langsung, kehilangan data, atau kehilangan pendapatan yang timbul dari penggunaan layanan. Tanggung jawab maksimum dibatasi pada jumlah yang telah kamu bayarkan kepada Clincoo dalam tiga bulan terakhir sebelum klaim. 10. Perubahan syarat Syarat ini dapat diperbarui seiring perkembangan layanan. Versi terbaru selalu tersedia di halaman ini dengan tanggal pembaruan. Perubahan penting akan diberitahukan lewat aplikasi atau email. Penggunaan layanan setelah pembaruan berarti kamu menerima versi terbaru. Pertanyaan seputar syarat ini dapat disampaikan lewat menu bantuan di aplikasi Clincoo."},{"i":"kebijakan-privasi","c":"legal","cn":"Legal","t":"Kebijakan Privasi Clincoo","d":"Bagaimana Clincoo mengumpulkan, memakai, menyimpan, dan melindungi datamu — beserta hak-hakmu atas data tersebut.","x":"Terakhir diperbarui: 3 Oktober 2026. Kebijakan ini menjelaskan bagaimana Clincoo menangani data pribadimu. Kami menulisnya dengan bahasa yang sesederhana mungkin karena percaya privasi bukan hal yang harus rumit. Data yang kami kumpulkan dan untuk apa Jenis data Contoh Tujuan Data akun Nama, email, foto profil Menjalankan akun dan autentikasi Data penggunaan Proyek dibuat, fitur dipakai Menjaga batas kuota paket bekerja benar Konten proyek File HTML/CSS/JS, gambar Menyimpan dan menerbitkan situsmu Data teknis Alamat IP, jenis perangkat Keamanan dan analitik agregat Data langganan Riwayat tagihan, status paket Mengelola paket berbayar Cara kami memakai data Data dipakai untuk: menjalankan layanan (menyimpan proyek, menerbitkan situs, menjaga kuota), mengamankan akun (deteksi penyalahgunaan), mengirim pemberitahuan penting seputar akun dan langgananmu, serta memperbaiki produk lewat analitik agregat. Kami tidak menjual data pribadimu. Tempat data disimpan Infrastruktur layanan berjalan di jaringan Cloudflare: file dan database disimpan di pusat data Cloudflare, dan situs yang kamu terbitkan disajikan lewat jaringan global mereka. Sebagian penyedia layanan pihak ketiga memproses data sebatas yang diperlukan untuk fungsinya — dijelaskan di bagian berbagi data di bawah. Cookie dan penyimpanan lokal Jenis Fungsi Bisa dihapus? Cookie sesi Menjaga kamu tetap login Ya — lewat pengaturan browser; sesi berakhir dan kamu cukup masuk lagi localStorage Preferensi tampilan (mis. mode gelap) Ya — lewat pengaturan browser Analitik Statistik kunjungan agregat Ya — tapi statistik anonim tidak mengenalmu secara pribadi Cookie pelacakan pihak ketiga untuk iklan tidak dipakai. AI dan kontenmu Saat kamu mengajukan pertanyaan ke asisten AI, konteks proyek yang relevan dikirim agar AI bisa menjawab tepat. Permintaan AI diproses untuk menghasilkan jawaban dan menjaga kualitas layanan; kami tidak menjual atau membagikan konten proyekmu untuk keperluan lain. Berbagi dengan pihak ketiga Pihak Data yang diproses Alasan Cloudflare File proyek, database, traffic Infrastruktur hosting dan jaringan Google / GitHub Data dasar akun saat login Penyedia login (OAuth) Penyedia email transaksional Alamat email Mengirim email layanan (verifikasi, notifikasi) Gerbang pembayaran Data transaksi langganan Memproses pembayaran paket berbayar Kami tidak membagikan data untuk periklanan. Retensi dan penghapusan Data akun disimpan selama akunmu aktif. Saat kamu menghapus akun lewat zona bahaya di pengaturan, data akun dan proyek dihapus dari sistem secara permanen dalam waktu wajar, kecuali data yang wajib disimpan oleh hukum (seperti catatan transaksi). Backup berkala juga dihapus sesuai siklus retensinya. Hak kamu Akses: data pribadimu bisa diekspor dari pengaturan akun. Koreksi: data yang salah bisa diperbaiki lewat pengaturan profil. Penghapusan: akun beserta seluruh datanya bisa dihapus kapan saja dari zona bahaya. Pertanyaan: hubungi lewat menu bantuan di aplikasi — permintaan ditindaklanjuti sesuai ketentuan perlindungan data yang berlaku. Kebijakan ini bisa diperbarui seiring perkembangan layanan. Versi terbaru selalu ada di halaman ini beserta tanggal pembaruan, dan perubahan penting diberitahukan lewat aplikasi atau email."},{"i":"cara-mengekspor-data-akun","c":"legal","cn":"Legal","t":"Cara Mengekspor Data Akun","d":"Langkah meminta salinan data akun dan proyek Clincoo sebelum pindah alat atau sekadar arsip pribadi.","x":"Kebijakan privasi Clincoo menyebut kamu bisa mengakses data pribadimu. Ekspor berguna sebelum mengganti perangkat, mengarsipkan klien, atau menutup akun. Dari pengaturan akun Masuk ke app.clincoo.buzz , buka pengaturan akun, lalu cari opsi ekspor data. Unduh arsip yang disediakan dan simpan di luar proyek yang sedang kamu edit. Yang ikut dan yang tidak Salinan biasanya mencakup profil dan file proyek yang tersimpan. Riwayat tagihan yang wajib disimpan secara hukum tetap di sistem pembayaran dan tidak selalu ada di arsip unduhan. Setelah mengunduh Buka arsip dan pastikan index.html serta aset penting ada. Jangan unggah arsip itu ke repositori publik. Kalau opsi ekspor tidak terlihat, minta lewat menu bantuan di aplikasi dengan subjek akses data."},{"i":"cara-menghapus-akun-dan-proyek","c":"legal","cn":"Legal","t":"Cara Menghapus Akun dan Proyek","d":"Tata cara menghapus proyek, mengosongkan sampah, lalu menutup akun Clincoo dari zona bahaya beserta akibatnya.","x":"Menghapus data di Clincoo bertahap. Proyek yang baru dihapus masih bisa dipulihkan dari sampah. Penghapusan akun dari zona bahaya bersifat permanen. Hapus satu proyek Di dashboard app.clincoo.buzz , pilih proyek lalu hapus. Selama belum dihapus permanen dari sampah, proyek bisa dipulihkan. Situs yang sudah dideploy tidak otomatis ikut turun hanya karena file dipindah ke sampah — cek status publish sebelum menutup pekerjaan klien. Tutup akun Buka pengaturan, gulir ke zona bahaya, lalu konfirmasi hapus akun. Ekspor data dulu kalau kamu masih butuh salinan. Setelah akun dihapus, profil dan proyek di sistem kami dihapus dalam jangka waktu wajar, kecuali data yang wajib disimpan hukum seperti catatan transaksi. Berhenti berlangganan tidak sama dengan hapus akun. Turun ke paket gratis dilakukan di halaman Langganan dan berlaku di akhir periode tagihan."},{"i":"cara-laporkan-penyalahgunaan-konten","c":"legal","cn":"Legal","t":"Cara Melaporkan Penyalahgunaan Konten","d":"Tata cara melaporkan situs atau unggahan di Clincoo yang melanggar hukum, meniru merek, atau menyalahgunakan data orang lain.","x":"Clincoo mengizinkan pengguna menerbitkan situs, tetapi tidak mengizinkan penipuan, peniruan merek, atau unggahan yang membocorkan data orang lain. Laporan dikirim dari akun di app.clincoo.buzz , bukan lewat komentar publik di docs.clincoo.buzz . Kumpulkan bukti dulu Salin URL lengkap situs yang bermasalah, termasuk jalur halaman. Catat waktu kamu melihatnya dan apa yang dilanggar: penipuan, ujaran yang mengancam, atau data pribadi. Simpan tangkapan layar. Jangan mengunduh atau menyebarkan data pribadi yang bocor. Kirim laporan Masuk ke akun Clincoo, buka bantuan akun, lalu pilih laporkan penyalahgunaan. Jelaskan dalam beberapa kalimat. Satu laporan untuk satu URL. Menyertakan tautan kedua hanya jika itu bagian dari situs yang sama. Jangan meminta penghapusan akun orang lain lewat chat AI di editor — asisten tidak menindak akun. Jika ini darurat keselamatan, hubungi pihak berwenang setempat sekaligus mengirim laporan. Laporan bohong yang berulang dapat menangguhkan akun pelapor, sesuai syarat layanan. Setelah terkirim Kamu menerima tanda bahwa laporan masuk. Peninjauan tidak selalu membalas dengan detail akun orang lain. Kalau URL sudah tidak bisa dibuka, tindakan mungkin sudah diterapkan."},{"i":"cara-mengatur-cookie-dan-izin","c":"legal","cn":"Legal","t":"Cara Mengatur Cookie dan Izin Browser","d":"Tata cara membaca cookie yang dipakai Clincoo, menolak izin yang tidak perlu, dan menulis pemberitahuan cookie di situsmu sendiri.","x":"Cookie sesi menjaga kamu tetap masuk di app.clincoo.buzz dan editor.clincoo.buzz . Cookie itu bukan izin untuk melacak pengunjung situs yang kamu deploy. Dua hal ini sering tercampur. Cookie akun Clincoo Buka pengaturan situs di browser untuk app.clincoo.buzz. Cookie sesi boleh tetap ada supaya tidak keluar setiap kali menyegarkan editor. Kalau kamu memakai komputer bersama, keluar dari akun setelah selesai, bukan hanya menutup tab. Izin yang tidak wajib Tolak notifikasi, kamera, dan lokasi kalau proyek tidak memakainya. Izin mikrofon tidak diperlukan untuk menyunting HTML. Menghapus cookie akan mengeluarkan akun. Simpan dulu pekerjaan di editor. Pemberitahuan di situsmu Jika situs yang kamu terbitkan memasang analitik pihak ketiga, tulis kalimat singkat di footer: apa yang disimpan, untuk apa, dan tautan ke kebijakan privasi. Jangan menyalin banner orang lain tanpa menyesuaikan alat yang benar-benar kamu pakai. Rincian pengumpulan data akun ada di kebijakan privasi Clincoo di blog ini."},{"i":"cara-pasang-tautan-kebijakan-privasi-di-footer","c":"legal","cn":"Legal","t":"Cara Pasang Tautan Kebijakan Privasi di Footer","d":"Tata cara menaruh tautan kebijakan privasi yang terlihat di setiap halaman situs yang kamu terbitkan lewat Clincoo.","x":"Pengunjung harus bisa menemukan kebijakan privasi tanpa mencari menu tersembunyi. Footer adalah tempat yang tetap ada di setiap halaman. Buat halaman kebijakan Tambah file privasi.html di proyek, atau satu bagian dengan id yang stabil. Tulis data apa yang dikumpulkan halaman itu: formulir, analitik, atau cookie. Jangan salin kebijakan situs lain jika alat yang kamu pakai berbeda. Tautkan dari footer Di setiap halaman, taruh tautan teks biasa, misalnya Kebijakan privasi, mengarah ke privasi.html. Hindari tautan yang hanya berupa ikon tanpa nama. Warna tautan harus tetap terbaca di atas warna footer. Samakan dengan yang benar-benar jalan Jika kamu belum memasang analitik, jangan mengaku memasangnya. Jika form mengirim nama dan email ke layanan lain, sebut layanan itu. Perbarui tanggal di atas halaman tiap kali daftar alat berubah. Kebijakan akun Clincoo tetap di blog ini. Kebijakan situs yang kamu buat adalah tanggung jawab proyekmu di editor.clincoo.buzz , lalu tayang setelah deploy."},{"i":"cara-cantumkan-lisensi-font-pihak-ketiga","c":"legal","cn":"Legal","t":"Cara Cantumkan Lisensi Font Pihak Ketiga","d":"Tata cara mengecek lisensi font yang dipakai di situs Clincoo lalu menaruh atribusi di footer atau halaman kredit.","x":"Font yang diunduh bukan otomatis bebas dipakai di situs klien. Sebelum deploy dari app.clincoo.buzz , baca lisensi file font yang ada di proyek. Cari nama lisensi di sumber font Di halaman unduhan, catat apakah lisensi SIL Open Font License, Apache, atau komersial yang melarang embed. OFL biasanya mengizinkan pakai di web asal nama font tidak dijual sebagai produk font baru. Lisensi desktop saja tidak selalu mengizinkan @font-face. Simpan berkas lisensi di proyek Letakkan OFL.txt atau LICENSE di folder font, jangan dihapus saat merapikan file di editor.clincoo.buzz . Jika lisensi meminta atribusi, tambahkan satu baris di footer: nama font, penulis, dan tautan lisensi. Jangan campur file berlisensi beda Mengganti nama file font tidak mengganti kewajiban lisensi. Kalau klien meminta font berbayar, simpan bukti pembelian di luar repo publik. Untuk font sistem seperti Georgia, atribusi tidak diperlukan. Kebijakan konten pengguna Clincoo ada di Syarat dan Ketentuan . Tanggung jawab lisensi aset tetap di pembuat situs."},{"i":"cara-tandai-cuplikan-kode-berlisensi","c":"legal","cn":"Legal","t":"Cara Tandai Cuplikan Kode Berlisensi","d":"Tata cara menyalin cuplikan dari dokumentasi atau repositori ke proyek Clincoo tanpa menghapus komentar lisensi.","x":"Cuplikan dari Stack Overflow, GitHub, atau dokumentasi punya syarat masing-masing. Menempelnya ke file di editor.clincoo.buzz tidak menghapus kewajiban itu. Baca lisensi sebelum menyalin File berlisensi MIT atau BSD biasanya boleh dipakai asal komentar hak cipta tetap ada. Kode tanpa lisensi di repositori orang lain jangan dianggap domain publik. Tulis ulang dengan kata dan strukturmu sendiri kalau lisensinya tidak jelas. Simpan komentar di atas fungsi Jangan buang blok komentar SPDX atau copyright saat merapikan. Satu baris cukup: sumber, penulis, dan tautan berkas asli. Kalau kamu mengubah fungsi, catat bahwa itu turunan, bukan salinan utuh. Pisahkan kode contoh Clincoo Contoh di dokumentasi Clincoo untuk dipelajari di proyekmu, bukan untuk dijual sebagai template utuh tanpa perubahan. Situs yang kamu deploy dari app.clincoo.buzz tetap milikmu selama aset pihak ketiga yang kamu tempel patuh pada lisensinya. Kalau ragu, tanyakan ke asisten AI Clincoo dengan menempelkan tautan sumber, bukan hanya kode tanpa konteks."},{"i":"cara-beri-atribusi-gambar-berlisensi","c":"legal","cn":"Legal","t":"Cara Beri Atribusi Gambar Berlisensi","d":"Tata cara menaruh kredit gambar stok atau ikon berlisensi di footer situs yang kamu deploy dari Clincoo.","x":"Gambar dari Unsplash, ikon berlisensi, atau ilustrasi orang lain tidak otomatis bebas dipakai hanya karena sudah tampil di preview. Kalau lisensinya minta kredit, tulis di situs yang kamu terbitkan dari app.clincoo.buzz . Cek syarat sebelum unduh Baca apakah kredit wajib, apakah boleh diubah, dan apakah boleh dipakai komersial. Simpan tautan halaman unduhan di catatan proyek. Jangan mengandalkan nama file saja. Tulis kredit yang bisa diklik Di footer, satu baris cukup: nama pembuat, sumber, dan tautan. Contoh: Foto oleh Nama via Unsplash. Letakkan dekat tautan kebijakan privasi supaya pengunjung menemukannya tanpa scroll panjang. Jangan hapus saat merapikan CSS Saat kamu memoles layout di editor.clincoo.buzz , pastikan blok kredit tidak ikut terhapus. Kalau gambar diganti, ganti juga baris kreditnya pada commit yang sama."},{"i":"cara-jangan-commit-kunci-api","c":"legal","cn":"Legal","t":"Cara Jangan Commit Kunci API","d":"Tata cara memisahkan kunci API dari repositori proyek Clincoo supaya tidak ikut terbit ke situs publik.","x":"Kunci API yang tertulis di file HTML atau JavaScript akan terbaca siapa pun yang membuka sumber halaman. Jangan menempelkannya di proyek yang kamu deploy dari app.clincoo.buzz . Pakai variabel lingkungan, bukan string di kode Simpan rahasia di pengaturan environment proyek, lalu baca lewat proses server kalau fiturnya ada. Di sisi browser, anggap semua konstanta terlihat. Panggil layanan lewat endpoint yang kamu kendalikan, bukan langsung dengan kunci di klien. Cek sebelum commit Sebelum commit pertama atau commit lanjutan di editor.clincoo.buzz , cari pola sk_ , api_key, dan token di pencarian file. Kalau ketemu, pindahkan, lalu commit penghapusannya. Kalau sudah terlanjur terbit Putar (rotate) kunci di penyedia layanan, anggap kunci lama bocor, dan deploy ulang. Menghapus baris dari file tidak menarik kembali salinan yang sudah diunduh orang."},{"i":"cara-buat-halaman-kontak-penanggung-jawab","c":"legal","cn":"Legal","t":"Cara Buat Halaman Kontak Penanggung Jawab","d":"Tata cara menambah halaman kontak pemilik situs yang di-deploy Clincoo, untuk laporan kesalahan dan permintaan data.","x":"Situs yang mengumpulkan formulir atau cookie sebaiknya punya satu halaman yang menyebut siapa yang bertanggung jawab. Buat file kontak.html di proyek editor.clincoo.buzz , lalu tautkan dari footer. Isi minimum yang jelas Nama atau nama usaha, email yang kamu pantau, dan kota operasional sudah cukup untuk situs kecil. Jangan menaruh nomor KTP atau alamat rumah kalau tidak wajib. Jelaskan bahwa formulir di situs ini dikirim ke email tersebut. Bedakan kontak Clincoo dan kontak situmu Pengunjung situmu bukan otomatis pengguna Clincoo. Arahkan bug editor ke pusat bantuan Clincoo, dan arahkan pertanyaan isi situs ke emailmu. Tautan kebijakan privasi tetap mengarah ke halamanmu sendiri. Cek setelah deploy Buka URL publik, kirim email percobaan, dan pastikan tautan footer tidak 404. Kalau kamu memakai domain kustom, tes di domain itu, bukan hanya di pratinjau."}];
